            setMissions(cleanMissions); 
            localStorage.setItem('teacher_missions', JSON.stringify(cleanMissions)); 
        }
        if (Array.isArray(data.materials)) { const cleanMaterials = data.materials.map((m: any) => ({ id: (m.id || m.Id || '').toString().trim(), title: m.title || m.Title || '', subject: m.subject || m.Subject || '', description: m.description || m.Description || '', contentCode: m.contentCode || m.ContentCode || '', createdAt: m.createdAt || m.CreatedAt || new Date().toISOString(), isActive: m.isActive !== undefined ? parseBool(m.isActive) : true })); setMaterials(cleanMaterials); localStorage.setItem('teacher_materials', JSON.stringify(cleanMaterials)); }

