                        </div>
                        )}

                        <AnnouncementBanner isActive={teacherSettings.isAnnouncementActive} message={teacherSettings.announcement} isUnlocked={isUnlocked} /> 
                        {userRole === 'teacher' && <TeacherActionCards setActiveTab={setActiveTab} />} 
                        {userRole === 'student' && ( <StudentHeroCard profile={studentProfile} styles={profileHeaderStyles} onOpenInventory={() => setIsInventoryOpen(true)} onOpenShop={() => setIsShopOpen(true)} /> )} 
                        {userRole === 'student' && <DailyInsights dailyFact={dailyFact} wordOfDay={studentProfile.lastWordOfDay} />} 
                        <div className="flex flex-col gap-8"> 
                        {userRole === 'student' && ( <> <StudentAnalytics profile={studentProfile} grades={grades} subjects={teacherSettings.subjects} students={students} /> <MaterialGrid materials={activeMaterials} onOpenMaterial={handleOpenMaterial} onSync={() => syncTeacherData(undefined, false)} isSyncing={isSyncing} /> <MissionGrid missions={activeMissions} onViewMission={setViewMission} onSync={() => syncTeacherData(undefined, false)} isSyncing={isSyncing} /> </> )} 
                        {userRole === 'teacher' && ( <> 
                          <MaterialGrid title="Laboratorium Digital Guru" description="Simulasi Front-of-Class" materials={teacherLabs} onOpenMaterial={handleOpenMaterial} onSync={() => syncTeacherData(undefined, false)} isSyncing={isSyncing} />
                          <AnalyticsDashboard students={students} grades={grades} subjects={teacherSettings.subjects} /> 
                          <RankingSection dailyData={dailyData} subjectChampions={subjectChampions} globalData={globalData} getProfileStyles={getProfileStyles} onStudentClick={(id) => setSelectedRankingStudent(id)} /> 
                        </> )}
                        </div> 
                        {userRole === 'student' && ( <KindnessBottle count={studentProfile.kindnessCount || 0} lastDate={studentProfile.lastKindnessDate} pendingStatus={kindnessStatus.hasPending} countToday={kindnessStatus.countToday} onAdd={(text) => handleKindnessSubmit(text)} onClaimReward={handleClaimReward} /> )} 
                        {userRole === 'student' && isShopOpen && ( <StudentShop profile={studentProfile} shopCategory={shopCategory} setShopCategory={setShopCategory} filteredShopItems={filteredShopItems} onPurchase={handlePurchase} onClose={() => setIsShopOpen(false)} /> )} 
                    </div> )}
                    {activeTab === 'petualangan' && <PetualanganPortal profile={studentProfile} onUpdateProfile={handleUpdateStudentProfile} students={students} setGlobalBusy={setGlobalBusy} isUnlocked={isUnlocked} />}
                    {activeTab === 'history' && <HistoryAktifitasPortal profile={studentProfile} grades={grades} missions={missions} kindnessSubmissions={kindnessSubmissions} />}
                    {activeTab === 'labmaya' && <LabMayaPortal gasUrl={teacherSettings.gasUrl} subjects={teacherSettings.subjects} onPublish={handleAddMaterial} onPublishLab={handleAddTeacherLab} setGlobalBusy={setGlobalBusy} isUnlocked={isUnlocked} myDeviceId={myDeviceId} />}
                    {activeTab === 'buatgim' && <RakitGimPortal gasUrl={teacherSettings.gasUrl} isUnlocked={isUnlocked} subjects={teacherSettings.subjects} onPublish={handleAddMission} setGlobalBusy={setGlobalBusy} myDeviceId={myDeviceId} />}
                    {activeTab === 'ecosystem' && <NarasiAIPortal gasUrl={teacherSettings.gasUrl} isUnlocked={isUnlocked} setGlobalBusy={setGlobalBusy} myDeviceId={myDeviceId} />}
                    {activeTab === 'generator' && <RakitAIPortal gasUrl={teacherSettings.gasUrl} isUnlocked={isUnlocked} setGlobalBusy={setGlobalBusy} myDeviceId={myDeviceId} />}
                    {activeTab === 'peralatan' && <GuruToolboxPortal isUnlocked={isUnlocked} setGlobalBusy={setGlobalBusy} myDeviceId={myDeviceId} settings={teacherSettings} />}
                    {activeTab === 'media' && <MediaKreatifPortal isUnlocked={isUnlocked} setGlobalBusy={setGlobalBusy} myDeviceId={myDeviceId} settings={teacherSettings} />}
                    {activeTab === 'gamifikasi' && <EngagementPortal isUnlocked={isUnlocked} students={students} settings={teacherSettings} setGlobalBusy={setGlobalBusy} />}
                    {activeTab === 'komunikasi' && <CommunicationPortal isUnlocked={isUnlocked} students={students} settings={teacherSettings} setGlobalBusy={setGlobalBusy} />}
                    {activeTab === 'panelguru' && userRole === 'teacher' && ( <PanelGuruPortal isUnlocked={isUnlocked} settings={teacherSettings} setSettings={setTeacherSettings} students={students} setStudents={setStudents} grades={grades} setGrades={setGrades} missions={missions} setMissions={setMissions} materials={materials} setMaterials={setMaterials} teacherLabs={teacherLabs} setTeacherLabs={setTeacherLabs} submissions={submissions} setSubmissions={setSubmissions} onSyncRequest={() => syncTeacherData(undefined, true)} setShowStudentDetail={setShowStudentDetail} kindnessSubmissions={kindnessSubmissions} setKindnessSubmissions={setKindnessSubmissions} setGlobalBusy={setGlobalBusy} setBusyMessage={setBusyMessage} myDeviceId={myDeviceId} onSubTabUpdate={setActiveSubTab} /> )}
                    </main>
                </div>
            </div>
          </div>

          {selectedRankingStudent && (() => { const student = students.find(s => (s.id || '').toString().trim() === selectedRankingStudent.toString().trim()); if (!student) return null; return ( <StudentRankingDetailModal student={student} grades={grades} subjects={teacherSettings.subjects} onClose={() => setSelectedRankingStudent(null)} /> ); })()}

          {viewMission && ( <MissionDetailModal mission={viewMission} onClose={() => setViewMission(null)} onStartGame={(m) => { 
            setGameInstanceKey(Date.now()); // Unique key for fresh start
            setActiveGameMission(m); 
            setViewMission(null); 
          }} onMarkFinished={(id) => handleFinishMission(id)} /> )}

          {isInventoryOpen && ( <InventoryModal profile={studentProfile} onUpdateProfile={handleUpdateStudentProfile} onClose={() => setIsInventoryOpen(false)} activeEditTab={activeEditTab} setActiveEditTab={setActiveEditTab} /> )}

          {/* OVERLAY LAB MAYA / MATERI EKSPLORASI - SLIM HEADER */}
          {activeLabMaterial && ( 
            <div ref={materialContainerRef} className="fixed inset-0 z-[7000] bg-slate-100 flex flex-col h-screen overflow-hidden animate-in slide-in-from-bottom duration-300"> 
              <div className="bg-emerald-600 p-2 md:p-3 shadow-lg flex justify-between items-center z-10 shrink-0">
                <div className="flex gap-3">
                  <div className="w-8 h-8 rounded-lg bg-white/20 flex items-center justify-center text-white"><i className="fas fa-flask text-sm"></i></div>
                  <div className="flex items-center">
                    <h3 className="text-white font-black uppercase text-[11px] md:text-xs Museum-Text leading-tight">{activeLabMaterial.title}</h3>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button onClick={toggleFullscreenMaterial} className="bg-white/10 hover:bg-emerald-500 text-white px-3 py-1.5 rounded-lg transition-all font-black text-[9px] uppercase border border-white/20">
                    <i className="fas fa-expand mr-1.5"></i> Layar Penuh
                  </button>
                  <button onClick={() => setActiveLabMaterial(null)} className="bg-white/10 hover:bg-red-50 text-white px-3 py-1.5 rounded-lg transition-all font-black text-[9px] uppercase border border-white/20">
                    <i className="fas fa-times mr-1.5"></i> Tutup
                  </button>
                </div>
              </div>
              <div className="flex-grow w-full relative bg-white min-h-0">
                <iframe 
                   key={`lab-instance-${activeLabMaterial.id}-${labInstanceKey}`} 
                   srcDoc={activeLabMaterial.contentCode} 
                   className="absolute inset-0 w-full h-full border-none" 
                   title="Lab Maya Player" 
                   sandbox="allow-scripts allow-same-origin allow-popups allow-forms" 
                />
              </div> 
            </div> 
          )}

          {/* OVERLAY GAME MISSION - SLIM FOOTER */}
          {activeGameMission && ( 
            <div className="fixed inset-0 z-[7000] bg-slate-900 flex flex-col h-screen overflow-hidden animate-in zoom-in duration-300" ref={gameContainerRef}> 
              <div className="flex-grow w-full relative bg-black flex items-center justify-center overflow-hidden min-h-0"> 
                <iframe 
                  key={`game-instance-${activeGameMission.id}-${gameInstanceKey}`}
                  srcDoc={activeGameMission.gameCode} 
                  className="absolute inset-0 w-full h-full border-none max-w-[100vw]" 
                  title="Game Player" 
                  scrolling="no" 
                  sandbox="allow-scripts allow-same-origin allow-popups allow-forms" 
                /> 
              </div> 
              <div className="bg-indigo-900 p-2 md:p-3 border-t-2 border-indigo-500 flex justify-between items-center z-10 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] shrink-0"> 
                <div className="flex items-center gap-3"> 
                  <div className="w-10 h-10 rounded-lg bg-indigo-600 flex items-center justify-center text-white border border-indigo-400 shadow-lg"> 
                    <i className="fas fa-gamepad text-xl animate-pulse"></i> 
                  </div> 
                  <div className="text-white hidden md:block"> 
                    <h3 className="font-black uppercase text-[11px] md:text-xs Museum-Text text-yellow-300 leading-tight">{activeGameMission.title}</h3> 
                  </div> 
                </div> 
                <div className="flex gap-2"> 
                  <button onClick={toggleFullscreenGame} className="px-4 py-2 bg-indigo-700 text-white font-black uppercase rounded-lg hover:bg-indigo-600 transition-all text-[9px] border border-indigo-500"><i className="fas fa-expand mr-1.5"></i> Layar Penuh</button> 
                  <button onClick={() => setActiveGameMission(null)} className="px-4 py-2 bg-slate-700 text-slate-300 font-black uppercase rounded-lg hover:bg-slate-600 transition-all text-[9px]">Keluar</button> 
                  <div className="px-3 py-2 bg-blue-900/50 border border-blue-500/50 rounded-lg flex items-center gap-2 hidden sm:flex"> 
                    <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse"></div> 
                    <span className="text-white font-black uppercase text-[8px] tracking-widest whitespace-nowrap">Target: {activeGameMission.minScore || 70}</span> 
                  </div> 
                </div> 
              </div> 
            </div> 
          )}
        </div>
      )}

      {isLoggedIn && isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[3999] animate-in fade-in lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      <style>{`
        @keyframes bounce-subtle { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
        .animate-bounce-subtle { animation: bounce-subtle 2s ease-in-out infinite; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .pro-bracket { z-index: 50; }
        .scrolling-text { animation: scroll-marquee 20s linear infinite; display: inline-block; }
        @keyframes scroll-marquee {
          0% { transform: translateX(100%); }
          100% { transform: translateX(-100%); }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { TeacherSettings, Student, GradeEntry, Mission, InteractiveMaterial, MissionSubmission, KindnessSubmission, RedemptionItem } from '../types';
import TabKonfigurasi from './guru/TabKonfigurasi';
import TabMisi from './guru/TabMisi';
import TabMateri from './guru/TabMateri';
import TabPoin from './guru/TabPoin';
import TabData from './guru/TabData';

const PanelGuruPortal: React.FC<{ 
  isUnlocked: boolean, 
  settings: TeacherSettings, 
  setSettings: (s: TeacherSettings) => void, 
  students: Student[], 
  setStudents: (s: Student[]) => void, 
  grades: GradeEntry[], 
  setGrades: (g: GradeEntry[]) => void,
  missions: Mission[],
  setMissions: (m: Mission[]) => void,
  materials: InteractiveMaterial[],
  setMaterials: (m: InteractiveMaterial[]) => void,
  teacherLabs: InteractiveMaterial[],
  setTeacherLabs: (m: InteractiveMaterial[]) => void,
  submissions: MissionSubmission[],
  setSubmissions: (s: MissionSubmission[]) => void,
  onSyncRequest: () => Promise<void>,
  setShowStudentDetail: (id: string | null) => void,
  kindnessSubmissions?: KindnessSubmission[],
  setKindnessSubmissions?: (k: KindnessSubmission[]) => void,
  setGlobalBusy?: (b: boolean) => void,
  setBusyMessage?: (m: string | undefined) => void,
  myDeviceId: string,
  onSubTabUpdate?: (tabId: string) => void
}> = ({ 
  isUnlocked, 
  settings, 
  setSettings, 
  students, 
  setStudents, 
  grades, 
  setGrades, 
  missions, 
  setMissions, 
  materials, 
  setMaterials, 
  teacherLabs,
  setTeacherLabs,
  submissions, 
  setSubmissions, 
  onSyncRequest, 
  setShowStudentDetail, 
  kindnessSubmissions = [], 
  setKindnessSubmissions = (_: KindnessSubmission[]) => {},
  setGlobalBusy = (_b: boolean) => {},
  setBusyMessage = (_m: string | undefined) => {},
  myDeviceId,
  onSubTabUpdate
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'config' | 'students' | 'missions' | 'materials' | 'point_management'>('missions');
  const [activePointSubTab, setActivePointSubTab] = useState<'system' | 'monitoring' | 'redemptions'>('system');

  useEffect(() => {
    if (onSubTabUpdate) onSubTabUpdate(activeSubTab);
  }, [activeSubTab, onSubTabUpdate]);

  const [newStudentName, setNewStudentName] = useState('');
  const [newStudentPin, setNewStudentPin] = useState('');
  const [newSubjectName, setNewSubjectName] = useState('');

  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);
  const [adjustExp, setAdjustExp] = useState<number>(0);
  const [adjustCoin, setAdjustCoin] = useState<number>(0);
  const [adjustReason, setAdjustReason] = useState<string>('');

  const [showActivationModal, setShowActivationModal] = useState(false);
  const [actionedIds, setActionedIds] = useState<Set<string>>(new Set());

  const missionFileRef = useRef<HTMLInputElement>(null);
  const materialFileRef = useRef<HTMLInputElement>(null);

  const [missionForm, setMissionForm] = useState<Partial<Mission>>({
    title: '',
    subject: settings.subjects[0] || 'IPAS',
    description: '',
    expReward: 50,
    coinReward: 20,
    deadline: new Date(Date.now() + 86400000).toISOString().split('T')[0]
  });

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');

  const pendingSubmissions = useMemo(() => 
    submissions.filter(s => s.status === 'finished' && !actionedIds.has((s.id || '').toString().trim()))
  , [submissions, actionedIds]);

  const pendingKindness = useMemo(() => 
    kindnessSubmissions.filter(k => k.status === 'pending' && !actionedIds.has((k.id || '').toString().trim()))
  , [kindnessSubmissions, actionedIds]);

  const missionAlertCount = useMemo(() => {
    return pendingSubmissions.length + pendingKindness.length;
  }, [pendingSubmissions, pendingKindness]);

  const pointsAlertCount = useMemo(() => {
    return students.reduce((acc, s) => {
      const pendingRedeems = (s.redemptions || []).filter(r => 
        r.status === 'pending' && !actionedIds.has(r.id.toString().trim())
      ).length;
      return acc + pendingRedeems;
    }, 0);
  }, [students, actionedIds]);

  const saveToGas = async (action: string, payload: any) => {
    if (!settings.gasUrl) return false;
    if (setGlobalBusy) setGlobalBusy(true);
    if (setBusyMessage) setBusyMessage("Sinkronisasi Cloud...");
    try {
      await fetch(settings.gasUrl, { 
        method: 'POST', 
        mode: 'no-cors', 
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action, ...payload }) 
      });
      return true;
    } catch (e) { 
      console.error("Sync Error:", e);
      return false;
    } finally { 
      if (setGlobalBusy) setGlobalBusy(false);
      if (setBusyMessage) setBusyMessage(undefined);
    }
  };

  const handleManualSync = async () => {
    if (!settings.gasUrl || !settings.gasUrl.startsWith('https://script.google.com/')) {
      alert("Harap masukkan Link GAS yang valid terlebih dahulu!");
      return;
    }
    setSyncStatus('syncing');
    try {
      await onSyncRequest();
      setSyncStatus('success');
    } catch (e) {
      setSyncStatus('error');
      alert("Gagal memuat data. Periksa kembali Link GAS Anda.");
    } finally {
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  };

  const copyShareLink = () => {
    if (!settings.gasUrl) {
      alert("Masukkan Link GAS Anda terlebih dahulu!");
      return;
    }
    const baseUrl = window.location.origin + window.location.pathname;
    const shareLink = `${baseUrl}?gas=${btoa(settings.gasUrl)}`;
    navigator.clipboard.writeText(shareLink);
    alert("LINK BERHASIL DISALIN!");
  };

  const handleFileUpload = (type: 'mission' | 'material', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target?.result as string;
      const fileName = file.name.replace('.html', '').replace(/_/g, ' ');

      if (type === 'mission') {
        const newMission: Mission = {
          id: Date.now().toString(),
          title: `Upload: ${fileName}`,
          subject: missionForm.subject || settings.subjects[0],
          description: "Misi hasil unggah file HTML mandiri.",
          expReward: missionForm.expReward || 50,
          coinReward: missionForm.coinReward || 20,
          deadline: missionForm.deadline || new Date(Date.now() + 86400000).toISOString().split('T')[0],
          isActive: true,
          gameCode: content
        };
        const updated = [newMission, ...missions];
        setMissions(updated);
        await saveToGas('updateMissions', { missions: updated });
      } else {
        // Default to student explorations for manual upload if needed
        const newMat: InteractiveMaterial = {
          id: Date.now().toString(),
          title: `Upload: ${fileName}`,
          subject: settings.subjects[0],
          description: "Materi hasil unggah file HTML mandiri.",
          contentCode: content,
          createdAt: new Date().toISOString(),
          isActive: true
        };
        const updated = [newMat, ...materials];
        setMaterials(updated);
        await saveToGas('updateMaterials', { materials: updated });
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleAddMission = async () => {
    if (!missionForm.title || !missionForm.description) return;
    const newMission: Mission = {
      id: Date.now().toString(),
      title: missionForm.title!,
      subject: missionForm.subject!,
      description: missionForm.description!,
      expReward: Number(missionForm.expReward),
      coinReward: Number(missionForm.coinReward),
      deadline: missionForm.deadline!,
      isActive: true
    };
    const updated = [newMission, ...missions];
    setMissions(updated);
    setMissionForm({ ...missionForm, title: '', description: '' });
    await saveToGas('updateMissions', { missions: updated });
  };

  const handleDeleteMission = async (id: string) => {
    const mid = id.toString().trim();
    if(!confirm("Hapus misi ini secara permanen dari basis data? (Siswa yang belum mengerjakan tidak akan bisa melihat misi ini lagi)")) return;

    const updated = missions.filter(m => m.id.toString().trim() !== mid);
    setMissions(updated);
    await saveToGas('updateMissions', { missions: updated });
  };

  const handleBulkDeleteMissions = async (ids: string[]) => {
    if (!confirm(`Hapus ${ids.length} misi terpilih secara permanen?`)) return;
    const normalizedIds = ids.map(id => id.toString().trim());
    const updated = missions.filter(m => !normalizedIds.includes(m.id.toString().trim()));
    setMissions(updated);
    await saveToGas('updateMissions', { missions: updated });
    alert("Berhasil menghapus misi terpilih!");
  };

  const handleDeleteSubmission = async (id: string) => {
    if (!confirm("Hapus laporan tugas ini dari daftar validasi?")) return;
    const sid = id.toString().trim();
    const updated = submissions.filter(s => (s.id || (s as any).ID).toString().trim() !== sid);
    setSubmissions(updated);
    await saveToGas('updateSubmissions', { submissions: updated });
  };

  const handleBulkDeleteSubmissions = async (ids: string[]) => {
    if (!confirm(`Hapus ${ids.length} laporan tugas terpilih dari daftar validasi?`)) return;
    const normalizedIds = ids.map(id => id.toString().trim());
    const updated = submissions.filter(s => !normalizedIds.includes((s.id || (s as any).ID).toString().trim()));
    setSubmissions(updated);
    await saveToGas('updateSubmissions', { submissions: updated });
    alert("Laporan tugas terpilih berhasil dihapus!");
  };

  const handleConfirmSubmission = async (sub: MissionSubmission, score: number) => {
    if (score < 0 || score > 100) { alert("Nilai harus 0-100!"); return; }
    const missionId = (sub.missionId || (sub as any).MissionId).toString().trim();
    const mission = missions.find(m => m.id.toString().trim() === missionId);
    if (!mission) return;

    const multiplier = score / 100;
    const finalExp = Math.round(mission.expReward * multiplier);
    const finalCoins = Math.round(mission.coinReward * multiplier);
    const targetSubId = (sub.id || (sub as any).ID).toString().trim();
    const targetStudentId = (sub.studentId || (sub as any).StudentId).toString().trim();

    setActionedIds(prev => new Set(prev).add(targetSubId));

    const updatedSubs = submissions.map(s => {
        const sId = (s.id || (s as any).ID).toString().trim();
        if (sId === targetSubId) return { ...s, status: 'confirmed' as const, score: score };
        return s;
    });
    setSubmissions(updatedSubs);

    const newGrade: GradeEntry = { studentId: targetStudentId, subject: mission.subject, score: score, date: new Date().toISOString(), missionId: missionId };
    const updatedGrades = [...grades, newGrade];
    setGrades(updatedGrades);

    const updatedStudents = students.map(st => {
      const stId = (st.id || (st as any).ID).toString().trim();
      if (stId === targetStudentId) {
        const newExp = Number(st.exp || 0) + finalExp;
        return { ...st, exp: newExp, coins: Number(st.coins || 0) + finalCoins, level: Math.floor(newExp / 200) + 1 };
      }
      return st;
    });
    setStudents(updatedStudents);

    await saveToGas('updateSubmissions', { submissions: updatedSubs });
    await saveToGas('updateGrades', { grades: updatedGrades });
    await saveToGas('updateStudents', { students: updatedStudents });
    alert("Berhasil dikonfirmasi!");
  };

  const handleApproveKindness = async (k: KindnessSubmission) => {
    if(!confirm(`Setujui kebaikan dari ${k.studentName}?`)) return;
    const targetId = (k.id || (k as any).ID).toString().trim();

    setActionedIds(prev => new Set(prev).add(targetId));

    const updatedKindness = kindnessSubmissions.map(item => {
        const itemId = (item.id || (item as any).ID).toString().trim();
        if (itemId === targetId) return { ...item, status: 'approved' as const };
        return item;
    });
    setKindnessSubmissions(updatedKindness);

    const updatedStudents = students.map(st => {
        const stId = (st.id || (st as any).ID).toString().trim();
        if (stId === k.studentId.toString().trim()) {
            return { ...st, coins: (st.coins || 0) + 10, kindnessCount: (st.kindnessCount || 0) + 1 };
        }
        return st;
    });
    setStudents(updatedStudents);

    await saveToGas('updateKindness', { submissions: updatedKindness });
    await saveToGas('updateStudents', { students: updatedStudents });
    alert("Kebaikan disetujui!");
  };

  const handleBulkApproveKindness = async (ids: string[]) => {
    if (!confirm(`Setujui ${ids.length} laporan kebaikan sekaligus?`)) return;

    const updatedKindness = [...kindnessSubmissions];
    const updatedStudents = [...students];
    const newActioned = new Set(actionedIds);
    const normalizedTargetIds = ids.map(id => id.toString().trim());

    normalizedTargetIds.forEach(targetId => {
      newActioned.add(targetId);
      const kIndex = updatedKindness.findIndex(item => (item.id || (item as any).ID).toString().trim() === targetId);

      if (kIndex !== -1 && updatedKindness[kIndex].status === 'pending') {
        updatedKindness[kIndex] = { ...updatedKindness[kIndex], status: 'approved' as const };
        const studentId = updatedKindness[kIndex].studentId.toString().trim();
        const sIndex = updatedStudents.findIndex(st => (st.id || (st as any).ID).toString().trim() === studentId);

        if (sIndex !== -1) {
          updatedStudents[sIndex] = { 
            ...updatedStudents[sIndex], 
            coins: (updatedStudents[sIndex].coins || 0) + 10,
            kindnessCount: (updatedStudents[sIndex].kindnessCount || 0) + 1 
          };
        }
      }
    });

    setKindnessSubmissions(updatedKindness);
    setStudents(updatedStudents);
    setActionedIds(newActioned);

    await saveToGas('updateKindness', { submissions: updatedKindness });
    await saveToGas('updateStudents', { students: updatedStudents });
    alert(`Berhasil menyetujui ${ids.length} kebaikan!`);
  };

  const handleRejectKindness = async (k: KindnessSubmission) => {
    if(!confirm("Tolak laporan ini?")) return;
    const targetId = (k.id || (k as any).ID).toString().trim();
    setActionedIds(prev => new Set(prev).add(targetId));
    const updatedKindness = kindnessSubmissions.map(item => {
        const itemId = (item.id || (item as any).ID).toString().trim();
        if (itemId === targetId) return { ...item, status: 'rejected' as const };
        return item;
    });
    setKindnessSubmissions(updatedKindness);
    await saveToGas('updateKindness', { submissions: updatedKindness });
  };

  const handleAddStudent = async () => {
    if (!newStudentName.trim() || !newStudentPin.trim()) return;
    const newStudent: Student = { id: Date.now().toString(), name: newStudentName.trim(), pin: newStudentPin.trim(), coins: 10, exp: 0, level: 1 };
    const updated = [...students, newStudent];
    setStudents(updated);
    setNewStudentName(''); setNewStudentPin('');
    await saveToGas('addStudent', { student: newStudent });
  };

  const handleApplyPoints = async () => {
    if (selectedStudentIds.length === 0) return;

    let updatedStudents = [...students];
    let updatedGrades = [...grades];

    selectedStudentIds.forEach(sid => {
        const targetSid = sid.toString().trim();
        const studentIndex = updatedStudents.findIndex(s => s.id.toString().trim() === targetSid);
        if (studentIndex !== -1) {
            const st = updatedStudents[studentIndex];
            const newExp = (st.exp || 0) + adjustExp;
            const newCoins = (st.coins || 0) + adjustCoin;
            updatedStudents[studentIndex] = {
                ...st,
                exp: newExp,
                coins: newCoins,
                level: Math.floor(newExp / 200) + 1
            };

            if (adjustExp !== 0 || adjustCoin !== 0) {
                updatedGrades.push({
                    studentId: targetSid,
                    subject: 'MANUAL REWARD',
                    score: 100,
                    date: new Date().toISOString(),
                    missionId: 'manual',
                    reason: adjustReason || 'Penyesuaian oleh Guru',
                    expChange: adjustExp,
                    coinChange: adjustCoin
                });
            }
        }
    });

    setStudents(updatedStudents);
    setGrades(updatedGrades);
    setSelectedStudentIds([]);
    setAdjustExp(0);
    setAdjustCoin(0);
    setAdjustReason('');

    await saveToGas('updateStudents', { students: updatedStudents });
    await saveToGas('updateGrades', { grades: updatedGrades });
    alert("Poin berhasil diperbarui!");
  };

  const handleProcessRedemption = async (studentId: string, redemptionId: string) => {
    if (!confirm("Konfirmasi bahwa hadiah fisik sudah diberikan kepada siswa?")) return;

    const sid = studentId.toString().trim();
    const rid = redemptionId.toString().trim();

    setActionedIds(prev => new Set(prev).add(rid));

    const updatedStudents = students.map(s => {
        if (s.id.toString().trim() === sid) {
            const redemptions = (s.redemptions || []).map(r => 
                r.id.toString().trim() === rid ? { ...r, status: 'used' as const } : r
            );

            let profileData = s.profileData;
            try {
                if (profileData) {
                    const pData = JSON.parse(profileData);
                    pData.redemptions = redemptions;
                    profileData = JSON.stringify(pData);
                }
            } catch (e) {}

            return { ...s, redemptions, profileData };
        }
        return s;
    });

    setStudents(updatedStudents);
    await saveToGas('updateStudents', { students: updatedStudents });
    alert("Penukaran berhasil diproses!");
  };

  const handleClearUsedRedemptions = async () => {
    if (!confirm("Hapus semua riwayat penukaran yang sudah selesai?")) return;

    const updatedStudents = students.map(s => {
        const redemptions = (s.redemptions || []).filter(r => r.status === 'pending');
        let profileData = s.profileData;
        try {
            if (profileData) {
                const pData = JSON.parse(profileData);
                pData.redemptions = redemptions;
                profileData = JSON.stringify(pData);
            }
        } catch (e) {}
        return { ...s, redemptions, profileData };
    });

    setStudents(updatedStudents);
    await saveToGas('updateStudents', { students: updatedStudents });
    alert("Histori dibersihkan!");
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation */}
      <div className="flex justify-center flex-wrap gap-2 md:gap-3 no-print">
        {[
          { id: 'missions', label: 'Manajemen Misi', icon: 'fa-tasks', alert: missionAlertCount },
          { id: 'materials', label: 'Manajemen Materi', icon: 'fa-flask' },
          { id: 'point_management', label: 'Manajemen Poin', icon: 'fa-coins', alert: pointsAlertCount },
          { id: 'students', label: 'Manajemen Data', icon: 'fa-database' },
          { id: 'config', label: 'Konfigurasi', icon: 'fa-cog' }
        ].map(tab => (
          <button 
            key={tab.id} 
            onClick={() => setActiveSubTab(tab.id as any)}
            className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all relative flex items-center gap-3 ${activeSubTab === tab.id ? 'bg-blue-600 text-white shadow-xl shadow-blue-200' : 'bg-white text-slate-400 hover:text-blue-600 shadow-sm border border-slate-100'}`}
          >
            <i className={`fas ${tab.icon}`}></i>
            <span className="hidden sm:inline">{tab.label}</span>
            {tab.alert > 0 && (
              <span className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center text-[9px] font-bold border-2 border-white animate-bounce">
                {tab.alert}
              </span>
            )}
          </button>
        ))}
      </div>

      <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
        {activeSubTab === 'config' && (
          <TabKonfigurasi 
            settings={settings} 
            setSettings={setSettings} 
            isUnlocked={isUnlocked} 
            setShowActivationModal={setShowActivationModal} 
            copyShareLink={copyShareLink} 
            handleManualSync={handleManualSync} 
            saveToGas={saveToGas}
            myDeviceId={myDeviceId}
          />
        )}
        {activeSubTab === 'missions' && (
          <TabMisi 
            missions={missions} 
            submissions={submissions} 
            kindnessSubmissions={kindnessSubmissions}
            settings={settings}
            missionForm={missionForm}
            setMissionForm={setMissionForm}
            handleAddMission={handleAddMission}
            handleFileUpload={handleFileUpload}
            missionFileRef={missionFileRef}
            handleManualSync={handleManualSync}
            syncStatus={syncStatus}
            handleDeleteMission={handleDeleteMission}
            handleBulkDeleteMissions={handleBulkDeleteMissions}
            handleDeleteSubmission={handleDeleteSubmission}
            handleBulkDeleteSubmissions={handleBulkDeleteSubmissions}
            handleConfirmSubmission={handleConfirmSubmission}
            handleApproveKindness={handleApproveKindness}
            handleBulkApproveKindness={handleBulkApproveKindness}
            handleRejectKindness={handleRejectKindness}
          />
        )}
        {activeSubTab === 'materials' && (
          <TabMateri 
            materials={materials} 
            setMaterials={setMaterials} 
            teacherLabs={teacherLabs}
            setTeacherLabs={setTeacherLabs}
            handleFileUpload={handleFileUpload} 
            materialFileRef={materialFileRef} 
            handleManualSync={handleManualSync} 
            syncStatus={syncStatus} 
            saveToGas={saveToGas}
          />
        )}
        {activeSubTab === 'point_management' && (
          <TabPoin 
            activePointSubTab={activePointSubTab}
            setActivePointSubTab={setActivePointSubTab}
            students={students}
            grades={grades}
            selectedStudentIds={selectedStudentIds}
            setSelectedStudentIds={setSelectedStudentIds}
            adjustExp={adjustExp}
            setAdjustExp={setAdjustExp}
            adjustCoin={adjustCoin}
            setAdjustCoin={setAdjustCoin}
            adjustReason={adjustReason}
            setAdjustReason={setAdjustReason}
            handleApplyPoints={handleApplyPoints}
            handleProcessRedemption={handleProcessRedemption}
            handleClearUsedRedemptions={handleClearUsedRedemptions}
            setShowStudentDetail={setShowStudentDetail}
          />
        )}
        {activeSubTab === 'students' && (
          <TabData 
            students={students} 
            setStudents={setStudents} 
            settings={settings} 
            setSettings={setSettings}
            newStudentName={newStudentName}
            setNewStudentName={setNewStudentName}
            newStudentPin={newStudentPin}
            setNewStudentPin={setNewStudentPin}
            newSubjectName={newSubjectName}
            setNewSubjectName={setNewSubjectName}
            handleAddStudent={handleAddStudent}
            saveToGas={saveToGas}
          />
        )}
      </div>

      {showActivationModal && (
        <div className="fixed inset-0 z-[10000] bg-slate-900/80 backdrop-blur-md flex items-center justify-center p-6">
           <div className="bg-white rounded-[3rem] p-10 max-w-md w-full shadow-2xl text-center border-b-8 border-amber-400">
              <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-3xl flex items-center justify-center text-3xl mx-auto mb-6"><i className="fas fa-crown"></i></div>
              <h3 className="text-2xl font-black Museum-Text uppercase text-slate-800 mb-2">Aktivasi Guru PRO</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase leading-relaxed mb-8">Hubungi Admin Mentari untuk mengaktifkan lisensi perangkat Anda dan membuka akses fitur premium tanpa batas.</p>
              <div className="space-y-3">
                <button onClick={() => window.open(`https://wa.me/6285755332389?text=Halo%20Admin%20Mentari,%20saya%20ingin%20aktivasi%20LISENSI%20GURU%20PRO%20untuk%20Device%20ID:%20${myDeviceId}`, '_blank')} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-emerald-100 active:scale-95 transition-all flex items-center justify-center gap-3">
                   <i className="fab fa-whatsapp text-lg"></i> HUBUNGI VIA WHATSAPP
                </button>
                <button onClick={() => setShowActivationModal(false)} className="w-full py-3 text-slate-400 font-black uppercase text-[9px] tracking-widest">Tutup</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default PanelGuruPortal;

import React, { useState } from 'react';
import { InteractiveMaterial } from '../../types';

interface TabMateriProps {
  materials: InteractiveMaterial[];
  setMaterials: (m: InteractiveMaterial[]) => void;
  teacherLabs: InteractiveMaterial[];
  setTeacherLabs: (m: InteractiveMaterial[]) => void;
  handleFileUpload: (type: 'material', e: React.ChangeEvent<HTMLInputElement>) => void;
  materialFileRef: React.RefObject<HTMLInputElement | null>;
  handleManualSync: () => void;
  syncStatus: string;
  saveToGas: (action: string, payload: any) => Promise<boolean>;
}

const TabMateri: React.FC<TabMateriProps> = ({
  materials, setMaterials, teacherLabs, setTeacherLabs, handleFileUpload, materialFileRef, handleManualSync, syncStatus, saveToGas
}) => {
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);
  const [selectedTeacherIds, setSelectedTeacherIds] = useState<string[]>([]);

  const toggleSelectStudent = (id: string) => {
    const sid = id.toString();
    setSelectedStudentIds(prev => prev.includes(sid) ? prev.filter(x => x !== sid) : [...prev, sid]);
  };

  const toggleSelectTeacher = (id: string) => {
    const sid = id.toString();
    setSelectedTeacherIds(prev => prev.includes(sid) ? prev.filter(x => x !== sid) : [...prev, sid]);
  };

  const toggleSelectAllStudent = () => {
    if (selectedStudentIds.length === materials.length && materials.length > 0) {
      setSelectedStudentIds([]);
    } else {
      setSelectedStudentIds(materials.map(m => m.id.toString()));
    }
  };

  const toggleSelectAllTeacher = () => {
    if (selectedTeacherIds.length === teacherLabs.length && teacherLabs.length > 0) {
      setSelectedTeacherIds([]);
    } else {
      setSelectedTeacherIds(teacherLabs.map(m => m.id.toString()));
    }
  };

  const handleBulkDeleteStudent = async () => {
    if (selectedStudentIds.length === 0) return;
    if (!confirm(`Hapus ${selectedStudentIds.length} materi eksplorasi siswa terpilih secara permanen?`)) return;

    const remainingMaterials = materials.filter(m => !selectedStudentIds.includes(m.id.toString()));
    setMaterials(remainingMaterials);
    setSelectedStudentIds([]);
    await saveToGas('updateMaterials', { materials: remainingMaterials });
    alert("Materi siswa terpilih berhasil dihapus!");
  };

  const handleBulkDeleteTeacher = async () => {
    if (selectedTeacherIds.length === 0) return;
    if (!confirm(`Hapus ${selectedTeacherIds.length} lab maya guru terpilih secara permanen?`)) return;

    const remainingLabs = teacherLabs.filter(m => !selectedTeacherIds.includes(m.id.toString()));
    setTeacherLabs(remainingLabs);
    setSelectedTeacherIds([]);
    await saveToGas('updateTeacherLabs', { labs: remainingLabs });
    alert("Lab guru terpilih berhasil dihapus!");
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500">
      <div className="flex items-center justify-between bg-white p-5 rounded-[2.5rem] border-4 border-emerald-100 shadow-xl no-print">
        <div className="flex items-center gap-4">
           <div className="w-12 h-12 rounded-2xl bg-emerald-500 text-white flex items-center justify-center text-2xl shadow-lg shadow-emerald-100"><i className="fas fa-flask"></i></div>
           <div>
              <h3 className="text-xl font-black Museum-Text uppercase text-emerald-600">Manajemen Lab Maya</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Kelola seluruh simulasi dan materi literasi aktif.</p>
           </div>
        </div>
        <button onClick={handleManualSync} className={`px-6 py-3 bg-white text-emerald-600 border-2 border-emerald-100 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-emerald-600 hover:text-white transition-all shadow-sm ${syncStatus === 'syncing' ? 'opacity-50' : ''}`}>
           <i className={`fas fa-sync-alt mr-2 ${syncStatus === 'syncing' ? 'fa-spin' : ''}`}></i> Sinkronisasi Cloud
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* BAGIAN 1: LABORATORIUM GURU */}
        <div className="glass-card rounded-[3.5rem] p-7 border-4 border-white bg-white shadow-xl flex flex-col min-h-[500px]">
           <div className="flex items-center justify-between mb-6 border-b-2 border-slate-50 pb-4">
              <h4 className="text-sm font-black uppercase text-blue-600 flex items-center gap-3"><i className="fas fa-chalkboard-user"></i> Laboratorium Guru</h4>
