            const raw = data.settings;
            let safeSubjects = ['IPAS', 'Bahasa Indonesia', 'Matematika', 'Pendidikan Pancasila', 'Bahasa Inggris'];
            if (Array.isArray(raw.subjects || raw.Subjects)) { safeSubjects = raw.subjects || raw.Subjects; }
