          .lg\:pl-64, .pl-0 { padding-left: 0 !important; }
          .pt-\[64px\], .md\:pt-\[72px\], .pt-4, .md\:pt-6, .pt-6, .md\:pt-10 { padding-top: 0 !important; }
          .pb-20 { padding-bottom: 0 !important; }
          .grid { display: block !important; }
          .lg\:col-span-7, .lg\:col-span-8, .lg\:col-span-12 { width: 100% !important; margin: 0 !important; }
          .shadow-2xl, .shadow-xl, .shadow-lg, .shadow-md, .shadow-sm { box-shadow: none !important; }
          .border-4, .border-8, .border-2 { border: 1px solid #e2e8f0 !important; }
          .rounded-\[3rem\], .rounded-\[4rem\], .rounded-\[3\.5rem\], .rounded-2xl { border-radius: 0 !important; }
          .printable-area { 
            display: block !important; 
            width: 100% !important; 
            position: static !important; 
            visibility: visible !important;
          }
        }
      `}</style>
    </div>
  );
};

export default App;

import { LessonFormData, GroundingSource } from '../types';
import { generateLessonPlan } from '../services/lessonPlanService';
import { AssemblyLoader, BlockingOverlay, ProRequirementNotice } from './SharedUI';
import { validateUsageCloud, getUsageStatusCloud } from '../services/validationService';
import React, { useState, useRef, useEffect, useMemo } from 'react';

const NarasiAIPortal: React.FC<{ gasUrl?: string, isUnlocked: boolean, setGlobalBusy: (b: boolean) => void, myDeviceId?: string }> = ({ gasUrl, isUnlocked, setGlobalBusy, myDeviceId }) => {
  const initialFormData: LessonFormData = {
    namaNIP: '',
    sekolah: '',
    kelasFase: 'Kelas 1 / Fase A',
    mataPelajaran: 'IPAS',
    muatanLokalNama: '',
    tahunPelajaran: '2024/2025',
    semester: 'Semester 1',
    alokasiWaktu: '2',
    jumlahPertemuan: '1',
    jamPelajaran: '35',
    modelPembelajaran: 'Discovery Learning',
    strategiPenerapan: 'Prinsip Understanding by Design (UbD)',
    tujuanpembelajaran: '',
    materipokok: '',
    capaianPembelajaran: ''
  };

  const [formData, setFormData] = useState<LessonFormData>(initialFormData);
  const [tujuanList, setTujuanList] = useState<string[]>(['']);
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [sources, setSources] = useState<GroundingSource[]>([]);
  const [copySuccess, setCopySuccess] = useState(false);
  const [isCloudBlocked, setIsCloudBlocked] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [proNotice, setProNotice] = useState<{show: boolean, title: string, feature: string, benefit: string, canClaimBonus?: boolean}>({
    show: false, title: '', feature: '', benefit: '', canClaimBonus: false
  });

  const [dailyCount, setDailyCount] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`usage_narasi_v2_${today}`);
    return saved ? parseInt(saved) : 0;
  });

  const [hasBonusToday, setHasBonusToday] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`bonus_narasi_v2_${today}`);
    return saved === 'true';
  });

  const resultRef = useRef<HTMLDivElement>(null);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const currentLimit = hasBonusToday ? 3 : 2;

  useEffect(() => {
    const checkCloud = async () => {
      if (!isUnlocked && myDeviceId) {
        setIsValidating(true);
        const isAllowed = await getUsageStatusCloud(myDeviceId, 'Modul Ajar', currentLimit, gasUrl || "NONE");
        if (!isAllowed) setIsCloudBlocked(true);
        setIsValidating(false);
      }
    };
    checkCloud();
  }, [isUnlocked, myDeviceId, currentLimit, gasUrl]);

  useEffect(() => {
    setFormData(prev => ({ 
      ...prev, 
      tujuanpembelajaran: tujuanList.filter(t => t.trim() !== '').join('\n') 
    }));
  }, [tujuanList]);

  const validationStatus = useMemo(() => {
    const missing = [];
    if (!formData.namaNIP.trim()) missing.push("Nama Pengajar / NIP");
    if (!formData.sekolah.trim()) missing.push("Nama Satuan Pendidikan (Sekolah)");
    if (!formData.tahunPelajaran.trim()) missing.push("Tahun Pelajaran");
    if (!formData.materipokok.trim()) missing.push("Materi Pokok / Judul Topik");
    if (!formData.capaianPembelajaran.trim()) missing.push("Capaian Pembelajaran (CP)");
    if (!tujuanList.some(t => t.trim() !== '')) missing.push("Minimal satu Tujuan Pembelajaran (TP)");
    return { isValid: missing.length === 0, missingFields: missing };
  }, [formData, tujuanList]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { id, value } = e.target;
    setFormData(prev => ({ ...prev, [id]: value }));
  };

  const handleReset = () => {
    if (window.confirm("Hapus semua data input?")) {
      setFormData(initialFormData);
      setTujuanList(['']);
      setResult(null);
      setSources([]);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleTujuanChange = (index: number, value: string) => {
    const newList = [...tujuanList];
    newList[index] = value;
    setTujuanList(newList);
  };

  const addTujuanField = () => {
    if (!isUnlocked) {
      setProNotice({
        show: true,
        title: 'Fitur Khusus Guru PRO',
        feature: 'Multi-Tujuan Pembelajaran',
        benefit: 'User PRO dapat memasukkan hingga 5 Tujuan Pembelajaran sekaligus untuk hasil modul yang lebih kompleks.'
      });
      return;
    }
    setTujuanList([...tujuanList, '']);
  };

  const removeTujuanField = (index: number) => {
    if (tujuanList.length > 1) {
      const newList = tujuanList.filter((_, i) => i !== index);
      setTujuanList(newList);
    }
  };

  const handleClaimBonus = () => {
    const today = new Date().toLocaleDateString();
    setHasBonusToday(true);
    localStorage.setItem(`bonus_narasi_v2_${today}`, 'true');
    setProNotice(prev => ({ ...prev, show: false }));
    setIsCloudBlocked(false); 
    alert("🌟 BONUS DIKLAIM!\n\nAnda mendapatkan 1 kesempatan tambahan untuk menyusun modul ajar hari ini. Silakan lanjutkan karya Anda!");
  };

  const handleGenerate = async () => {
    if (!isUnlocked) {
        if (dailyCount === 2 && !hasBonusToday) {
            setProNotice({
                show: true,
                title: 'Kuota Harian Penuh',
                feature: 'Kesempatan Ekstra Menanti',
                benefit: 'Bapak/Ibu masih bisa menyusun 1 modul ajar lagi hari ini secara GRATIS dengan membagikan aplikasi ini.',
                canClaimBonus: true
            });
            return;
        }
        if (dailyCount >= 3 || (isCloudBlocked && !hasBonusToday)) {
            setProNotice({
                show: true,
                title: 'Limit Harian Tercapai',
                feature: 'Generator Tanpa Batas',
                benefit: 'Akun Basic dibatasi pembuatan modul harian. Upgrade ke PRO untuk menikmati pembuatan modul sepuasnya tanpa batas waktu dan tanpa iklan share.',
                canClaimBonus: false
            });
            return;
        }
    }

    if (!validationStatus.isValid) {
      alert("Lengkapi data: " + validationStatus.missingFields.join(", "));
      return;
    }

    setIsLoading(true);
    setGlobalBusy(true);

    try {
      if (!isUnlocked && myDeviceId) {
        const isAllowed = await getUsageStatusCloud(myDeviceId, 'Modul Ajar', currentLimit, gasUrl || "NONE");
        if (!isAllowed) {
            setIsLoading(false);
            setGlobalBusy(false);
            setIsCloudBlocked(true);
            setProNotice({
                show: true,
                title: 'Limit Cloud Tercapai',
                feature: 'Keamanan Kuota Lintas Browser',
                benefit: 'Sistem mendeteksi perangkat atau kelas ini sudah menggunakan kuota harian. Gunakan akun PRO untuk akses tanpa batas.',
                canClaimBonus: !hasBonusToday
            });
            return; 
        }
      }

      setResult(null);
      const payload = { ...formData, tujuanpembelajaran: tujuanList.filter(t => t.trim() !== '').join('\n') };
      const { text, sources: rawSources } = await generateLessonPlan(payload);
      setResult(text);
      setSources(rawSources);

      if (!isUnlocked) {
        const today = new Date().toLocaleDateString();
        const newCount = dailyCount + 1;
        setDailyCount(newCount);
        localStorage.setItem(`usage_narasi_v2_${today}`, newCount.toString());
      }

      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 500);
    } catch (err: any) {
      alert("Terjadi kesalahan. Cek koneksi Anda.");
    } finally { 
        setIsLoading(false); 
        setGlobalBusy(false);
    }
  };

  const handleCopyToSpreadsheet = async () => {
    if (!printAreaRef.current) return;
    try {
      const htmlContent = printAreaRef.current.innerHTML;
      const type = "text/html";
      const blob = new Blob([htmlContent], { type });
      await navigator.clipboard.write([new ClipboardItem({ [type]: blob })]);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 3000);
      alert("Berhasil disalin!");
    } catch (err) { alert("Gagal menyalin data."); }
  };

  const handleDownloadDoc = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Modul Ajar</title><style>body { font-family: 'Arial', sans-serif; font-size: 11pt; line-height: 1.4; } table { border-collapse: collapse; width: 100%; margin-bottom: 10pt; } th, td { border: 1px solid black; padding: 5pt 8pt; text-align: left; font-size: 10pt; color: black; line-height: 1.2; } h1 { text-align: center; text-transform: uppercase; border-bottom: 2pt solid black; color: black; font-size: 16pt; margin-top: 10pt; margin-bottom: 15pt; } h2 { margin-top: 15pt; margin-bottom: 8pt; text-transform: uppercase; border-bottom: 1pt solid #ccc; color: black; font-size: 13pt; font-weight: bold; } p { color: black; margin-top: 0; margin-bottom: 8pt; }</style></head><body>";
    const footer = "</body></html>";
    const blob = new Blob(['\ufeff', header + content + footer], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `ModulAjar_${formData.mataPelajaran}_${formData.materipokok.replace(/\s+/g, '_')}.doc`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const parseInline = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, i) => 
      part.startsWith('**') && part.endsWith('**') 
      ? <strong key={i} className="text-black font-bold">{part.slice(2, -2)}</strong> 
      : part
    );
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    const elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];
    let isInsideTable = false;

    const flushTable = (index: number) => {
      if (currentTable.length > 0) {
        // FILTER: Hilangkan baris separator Markdown (---)
        const filteredTable = currentTable.filter(row => {
          const rowText = row.join('').trim();
          return rowText !== '' && !rowText.match(/^[:\-\s|]+$/);
        });

        if (filteredTable.length > 0) {
          elements.push(
            <div key={`table-${index}`} className="mb-6 border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
              <table className="w-full border-collapse bg-white text-black text-[11px]">
                <thead>
                  <tr className="bg-slate-50">
                    {filteredTable[0].map((cell, j) => (
                      <th key={j} className="border border-slate-200 py-3 px-4 font-bold text-left uppercase text-slate-700 tracking-wider">
                        {parseInline(cell.trim())}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filteredTable.slice(1).map((row, i) => (
                    <tr key={i} className="hover:bg-blue-50/30 transition-colors border-b border-slate-100 last:border-0">
                      {row.map((cell, j) => (
                        <td key={j} className="border-r border-slate-100 last:border-0 py-2.5 px-4 align-top leading-relaxed">
                          {parseInline(cell.trim())}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        currentTable = [];
      }
      isInsideTable = false;
    };

    lines.forEach((line, idx) => {
      const trimmed = line.trim();

      if (trimmed.startsWith('Bondowoso,')) {
          flushTable(idx);
          elements.push(
            <div key={`sig-${idx}`} className="mt-12 ml-auto w-72 text-left text-sm">
                {lines.slice(idx).map((sigLine, sIdx) => {
                    const t = sigLine.trim();
                    if (!t || t === '[KOSONG]') return <div key={sIdx} className={t === '[KOSONG]' ? "h-16" : ""}></div>;
                    return <p key={sIdx} className={`mb-1 ${t.startsWith('NIP.') ? 'font-medium text-slate-500 italic' : 'font-bold text-slate-900'}`}>{parseInline(sigLine)}</p>;
                })}
            </div>
          );
          return;
      }
      if (lines.slice(0, idx).some(l => l.trim().startsWith('Bondowoso,'))) return;

      if (trimmed.startsWith('|')) {
        isInsideTable = true;
        currentTable.push(trimmed.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1));
        return;
      } else if (isInsideTable && !trimmed.startsWith('|')) { 
        flushTable(idx); 
      }

      if (trimmed.startsWith('# ')) {
        elements.push(<h1 key={idx} className="text-2xl font-extrabold text-blue-800 uppercase my-8 text-center pb-4 border-b-4 border-blue-500 Museum-Text">{parseInline(trimmed.substring(2))}</h1>);
      } else if (trimmed.startsWith('## ')) {
        elements.push(<h2 key={idx} className="text-lg font-bold mt-10 mb-4 text-blue-700 border-b-2 border-blue-100 pb-2 uppercase flex items-center gap-3 Museum-Text">
          <span className="w-2.5 h-8 bg-blue-600 rounded-full"></span>
          {parseInline(trimmed.substring(3))}
        </h2>);
      } else if (!isInsideTable && trimmed !== '') {
        elements.push(<p key={idx} className="mb-3 text-slate-700 leading-relaxed text-[14px]">{parseInline(trimmed)}</p>);
      }
    });
    return elements;
  };

  return (
    <div className="animate-in fade-in duration-700">
      <BlockingOverlay isVisible={isLoading} text="Menyusun Modul Ajar..." isUnlocked={isUnlocked} />

      <ProRequirementNotice 
        isOpen={proNotice.show}
        onClose={() => setProNotice({...proNotice, show: false})}
        featureName={proNotice.feature}
        benefitDesc={proNotice.benefit}
        title={proNotice.title}
        deviceId={myDeviceId}
        canClaimBonus={proNotice.canClaimBonus}
        onShareBonus={handleClaimBonus}
      />

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-5 space-y-8 no-print">
          <div className="glass-card rounded-[2.5rem] p-8 border-t-8 border-t-blue-500 shadow-xl bg-white">
            <div className="flex items-center justify-between mb-6">
              <h2 className="font-bold text-blue-600 flex items-center uppercase tracking-wider text-sm Museum-Text">
                <i className="fas fa-pencil-alt mr-3 text-xl"></i> Pengisian Modul
              </h2>
              <button onClick={handleReset} className="text-[10px] font-bold text-red-500 hover:bg-red-50 px-3 py-1.5 rounded-full transition-all border border-red-200 active:scale-90">
                <i className="fas fa-undo mr-1"></i> RESET
              </button>
            </div>

            <div className="space-y-6">
                <div className="space-y-4">
                  <h3 className="text-xs font-black text-blue-800/40 uppercase tracking-[0.2em] flex items-center gap-3">
                    <span className="w-8 h-1 bg-blue-400 rounded-full"></span> BIODATA
                  </h3>
                  <div className="space-y-3">
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Nama Pengajar / NIP <span className="text-red-500">*</span></label>
                      <input id="namaNIP" value={formData.namaNIP} onChange={handleInputChange} className="w-full input-futuristic bg-white px-5 py-3.5 text-sm font-semibold" placeholder="Contoh: Budi Santoso, S.Pd / 1985..." />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Nama Sekolah <span className="text-red-500">*</span></label>
                      <input id="sekolah" value={formData.sekolah} onChange={handleInputChange} className="w-full input-futuristic bg-white px-5 py-3.5 text-sm font-semibold" placeholder="SDN 1 Mentari" />
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <h3 className="text-xs font-black text-blue-800/40 uppercase tracking-[0.2em] flex items-center gap-3">
                    <span className="w-8 h-1 bg-yellow-400 rounded-full"></span> KURIKULUM
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Fase / Kelas</label>
                      <select id="kelasFase" value={formData.kelasFase} onChange={handleInputChange} className="w-full input-futuristic px-4 py-3.5 text-sm font-semibold cursor-pointer">
                        <option>Kelas 1 / Fase A</option><option>Kelas 2 / Fase A</option><option>Kelas 3 / Fase B</option><option>Kelas 4 / Fase B</option><option>Kelas 5 / Fase C</option><option>Kelas 6 / Fase C</option><option>Kelas 7 / Fase D</option><option>Kelas 8 / Fase D</option><option>Kelas 9 / Fase D</option><option>Kelas 10 / Fase E</option><option>Kelas 11 / Fase F</option><option>Kelas 12 / Fase F</option>
                      </select>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Mata Pelajaran</label>
                      <select id="mataPelajaran" value={formData.mataPelajaran} onChange={handleInputChange} className="w-full input-futuristic px-4 py-3.5 text-sm font-semibold cursor-pointer">
                        <option value="IPAS">IPAS</option><option value="Bahasa Indonesia">Bahasa Indonesia</option><option value="Matematika">Matematika</option><option value="Pendidikan Pancasila">Pendidikan Pancasila</option><option value="Bahasa Inggris">Bahasa Inggris</option><option value="Seni Rupa">Seni Rupa</option><option value="Lainnya">Lainnya...</option>
                      </select>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Thn Pelajaran <span className="text-red-500">*</span></label>
                      <select id="tahunPelajaran" value={formData.tahunPelajaran} onChange={handleInputChange} className="w-full input-futuristic px-4 py-3.5 text-sm font-semibold cursor-pointer">
                        <option>2024/2025</option><option>2025/2026</option><option>2026/2027</option><option>2027/2028</option>
                      </select>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Semester</label>
                      <select id="semester" value={formData.semester} onChange={handleInputChange} className="w-full input-futuristic px-4 py-3.5 text-sm font-semibold">
                        <option>Semester 1</option><option>Semester 2</option>
                      </select>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <h3 className="text-xs font-black text-blue-800/40 uppercase tracking-[0.2em] flex items-center gap-3">
                    <span className="w-8 h-1 bg-green-400 rounded-full"></span> MATERI
                  </h3>
                  <div className="space-y-4">
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Judul Topik <span className="text-red-500">*</span></label>
                      <input id="materipokok" value={formData.materipokok} onChange={handleInputChange} className="w-full input-futuristic bg-white px-5 py-3.5 text-sm font-semibold" placeholder="Contoh: Energi Alternatif" />
                    </div>
                    <div className="space-y-3">
                      <div className="flex items-center justify-between ml-1">
                        <label className="text-[11px] font-bold text-slate-600 uppercase">Tujuan Pembelajaran <span className="text-red-500">*</span></label>
                        <button onClick={addTujuanField} className="text-[10px] font-black uppercase text-blue-600 hover:underline">+ Tambah TP</button>
                      </div>
                      {tujuanList.map((tujuan, idx) => (
                        <div key={idx} className="flex gap-2">
                          <input value={tujuan} onChange={(e) => handleTujuanChange(idx, e.target.value)} className="w-full input-futuristic px-4 py-3 text-sm font-semibold" placeholder={`TP ${idx + 1}...`} />
                          {tujuanList.length > 1 && (
                            <button onClick={() => removeTujuanField(idx)} className="w-12 h-12 rounded-xl bg-red-50 text-red-500 flex items-center justify-center border-2 border-red-100"><i className="fas fa-trash-alt"></i></button>
                          )}
                        </div>
                      ))}
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[11px] font-bold text-slate-600 uppercase ml-1">Capaian Pembelajaran <span className="text-red-500">*</span></label>
                      <textarea id="capaianPembelajaran" value={formData.capaianPembelajaran} onChange={handleInputChange} className="w-full input-futuristic rounded-2xl px-5 py-3.5 text-sm h-28 resize-none font-semibold Museum-Text" placeholder="Tulis atau salin CP di sini..." />
                    </div>
                  </div>
                </div>
            </div>

            <div className="mt-8">
              <button onClick={handleGenerate} disabled={isLoading || isValidating} className={`w-full py-5 font-bold rounded-2xl Museum-Text uppercase text-lg joyful-shadow bg-blue-600 text-white hover:bg-blue-700 active:scale-95 transition-all`}>
                {isLoading ? <><i className="fas fa-spinner fa-spin mr-3"></i>Menyusun...</> : <><i className="fas fa-wand-magic-sparkles mr-3"></i>Buat Modul Ajar</>}
              </button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-7" ref={resultRef}>
          {!result && !isLoading && (
            <div className="h-full min-h-[700px] flex flex-col items-center justify-center bg-white/50 border-4 border-dashed border-blue-200 rounded-[3rem] p-20 text-center">
              <div className="w-32 h-32 bg-blue-50 rounded-full flex items-center justify-center mb-10"><i className="fas fa-file-invoice text-blue-200 text-6xl"></i></div>
              <h3 className="text-xl font-bold text-blue-300 uppercase Museum-Text">DRAFT KOSONG</h3>
            </div>
          )}
          {isLoading && <AssemblyLoader />}
          {result && (
            <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border-4 border-blue-500 flex flex-col h-full animate-in zoom-in">
              <div className="p-6 bg-blue-500 flex flex-wrap gap-4 justify-center no-print">
                <button onClick={() => { navigator.clipboard.writeText(result); alert("Disalin!"); }} className="px-6 py-3 text-xs font-bold rounded-xl bg-white text-blue-600 uppercase joyful-shadow"><i className="fas fa-copy mr-2"></i> Salin</button>
                <button onClick={handleDownloadDoc} className="px-6 py-3 text-xs font-bold bg-white text-blue-600 rounded-xl uppercase joyful-shadow"><i className="fas fa-file-word mr-2"></i> Word</button>
                <button onClick={() => window.print()} className="px-6 py-3 text-xs font-bold bg-white text-blue-600 rounded-xl uppercase joyful-shadow"><i className="fas fa-print mr-2"></i> Cetak PDF</button>
              </div>
              <div className="bg-slate-50 p-8 md:p-16 overflow-auto flex-grow">
                <div ref={printAreaRef} className="bg-white shadow-xl mx-auto w-full p-[15mm] text-black rounded-sm min-h-[1000px] document-body printable-area">
                  {renderFormattedContent(result)}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default NarasiAIPortal;

import { AssessmentFormData } from '../types';
import { generateAssessment } from '../services/assessmentService';
import { getInitialAssessmentData } from '../constants';
import { AssemblyLoader, AIImage, BlockingOverlay, ProRequirementNotice } from './SharedUI';
import { validateUsageCloud, getUsageStatusCloud } from '../services/validationService';
import React, { useState, useRef, useEffect, useMemo } from 'react';

const RakitAIPortal: React.FC<{ gasUrl?: string, isUnlocked: boolean, setGlobalBusy: (b: boolean) => void, myDeviceId?: string }> = ({ gasUrl, isUnlocked, setGlobalBusy, myDeviceId }) => {
  const [formData, setFormData] = useState<AssessmentFormData>(getInitialAssessmentData());
  const [activeFormTab, setActiveFormTab] = useState<'identity' | 'structure' | 'topics'>('identity');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [copySuccess, setCopySuccess] = useState(false);
  const [isCloudBlocked, setIsCloudBlocked] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [dailyCount, setDailyCount] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`usage_asesmen_v1_${today}`);
    return saved ? parseInt(saved) : 0;
  });

  const [hasBonusToday, setHasBonusToday] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`bonus_asesmen_v1_${today}`);
    return saved === 'true';
  });

  const [proNotice, setProNotice] = useState<{show: boolean, title: string, feature: string, benefit: string, canClaimBonus?: boolean}>({
    show: false, title: '', feature: '', benefit: '', canClaimBonus: false
  });

  const [showConfirmModal, setShowConfirmModal] = useState<{show: boolean, missing: string[]}>({show: false, missing: []});

  const resultRef = useRef<HTMLDivElement>(null);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const currentLimit = hasBonusToday ? 2 : 1;

  useEffect(() => {
    const checkCloud = async () => {
      if (!isUnlocked && myDeviceId) {
        setIsValidating(true);
        const isAllowed = await getUsageStatusCloud(myDeviceId, 'Asesmen', currentLimit, gasUrl || "NONE");
        if (!isAllowed) setIsCloudBlocked(true);
        setIsValidating(false);
      }
    };
    checkCloud();
  }, [isUnlocked, myDeviceId, currentLimit, gasUrl]);

  const calculateTotalFromFormats = () => formData.formats.reduce((acc, curr) => acc + (parseInt(curr.count) || 0), 0);
  const calculateTotalWeight = () => formData.topics.reduce((acc, curr) => acc + (parseInt(curr.bobot) || 0), 0);
  const totalCalculatedSoal = calculateTotalFromFormats();
  const totalWeight = calculateTotalWeight();
  const isSoalMatching = (parseInt(formData.jumlahSoalTotal) || 0) === totalCalculatedSoal && totalCalculatedSoal > 0;
  const isWeightMatching = totalWeight === 100;

  const handleClaimBonus = () => {
    const today = new Date().toLocaleDateString();
    setHasBonusToday(true);
    localStorage.setItem(`bonus_asesmen_v1_${today}`, 'true');
    setProNotice(prev => ({ ...prev, show: false }));
    setIsCloudBlocked(false); 
    alert("🌟 BONUS DIKLAIM!\n\nSatu kesempatan tambahan untuk membuat asesmen telah aktif. Ayo selesaikan naskah soal Anda!");
  };

  const handleGenerate = async () => {
    if (!isUnlocked) {
        if (dailyCount === 1 && !hasBonusToday) {
            setProNotice({
                show: true,
                title: 'Kuota Harian Penuh',
                feature: 'Hadiah Kejutan Petualang',
                benefit: 'Bapak/Ibu masih bisa membuat 1 naskah soal lagi hari ini secara GRATIS dengan membagikan kabar baik ini ke rekan sejawat.',
                canClaimBonus: true
            });
            return;
        }
        if (dailyCount >= 2 || (isCloudBlocked && !hasBonusToday)) {
            setProNotice({
                show: true,
                title: 'Limit Harian Tercapai',
                feature: 'Generator Soal Tak Terbatas',
                benefit: 'User Basic dibatasi 1 asesmen per hari (+1 bonus share). Upgrade ke GURU PRO untuk membuat naskah sepuasnya tanpa batasan.',
                canClaimBonus: false
            });
            return;
        }
    }

    const missing = [];
    if (!formData.judulAsesmen.trim()) missing.push("Judul Asesmen belum diisi.");
    if (!isSoalMatching) missing.push("Jumlah rincian soal tidak sesuai target total.");
    if (!isWeightMatching) missing.push(`Total bobot materi harus tepat 100% (saat ini ${totalWeight}%).`);

    if (missing.length > 0) { 
      setShowConfirmModal({ show: true, missing }); 
      return; 
    }

    setIsLoading(true);
    setGlobalBusy(true);

    try {
      setResult(null);
      const { text } = await generateAssessment(formData);
      setResult(text);

      if (!isUnlocked) {
        const today = new Date().toLocaleDateString();
        const newCount = dailyCount + 1;
        setDailyCount(newCount);
        localStorage.setItem(`usage_asesmen_v1_${today}`, newCount.toString());
      }

      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 500);
    } catch (err) { alert("Waduh! Gangguan mesin soal."); } finally { 
        setIsLoading(false); 
        setGlobalBusy(false);
    }
  };

  const handleCopyToSpreadsheet = async () => {
    if (!printAreaRef.current) return;
    try {
      const htmlContent = printAreaRef.current.innerHTML;
      const type = "text/html";
      const blob = new Blob([htmlContent], { type });
      await navigator.clipboard.write([new ClipboardItem({ [type]: blob })]);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 3000);
      alert("Berhasil disalin!");
    } catch (err) { alert("Gagal menyalin."); }
  };

  const handleDownloadDoc = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Asesmen</title><style>table { border-collapse: collapse; width: 100%; color: #000000; margin-bottom: 8pt; border: 1px solid black; } td, th { padding: 4pt 6pt; vertical-align: top; border: 1px solid black; font-family: 'Arial', sans-serif; font-size: 10pt; line-height: 1.2; } .kop-table-container table { border: none !important; } .kop-table-container td { border: none !important; padding: 1pt 2pt; } p { margin: 0; padding: 0; margin-bottom: 3pt; line-height: 1.2; } .section-header { font-weight: bold; border-bottom: 1.5pt solid black; margin-top: 10pt; margin-bottom: 5pt; display: block; text-transform: uppercase; font-size: 11pt; }</style></head><body>`;
    const footer = "</body></html>";
    const blob = new Blob(['\ufeff', header + content + footer], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Asesmen_${formData.judulAsesmen.replace(/\s+/g, '_')}.doc`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const renderContent = (content: string) => {
    const lines = content.split('\n');
    const elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];
    let inTable = false;

    const parseFormattedText = (text: string) => {
      let html = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
      html = html.replace(/__(.*?)__/g, '<i>$1</i>');
      return <span dangerouslySetInnerHTML={{ __html: html }} />;
    };

    const flushTable = (idx: number) => {
      if (currentTable.length > 0) {
        // FILTER: Sembunyikan baris separator Markdown (---)
        const filteredRows = currentTable.filter(row => {
          const rowText = row.join('').trim();
          return rowText !== '' && !rowText.match(/^[:\-\s|]+$/);
        });

        if (filteredRows.length > 0) {
          const isIdentity = filteredRows.some(row => row.some(cell => cell.toLowerCase().includes('siswa') || cell.toLowerCase().includes('sekolah')));
          elements.push(
            <div key={`tbl-${idx}`} className={`w-full mb-6 overflow-x-auto ${isIdentity ? 'kop-table-container' : 'border border-black'}`}>
              <table className={`w-full border-collapse text-[11px] leading-tight`} border={isIdentity ? 0 : 1} style={{ width: '100%', color: 'black', borderCollapse: 'collapse' }}>
                <tbody>{filteredRows.map((r, i) => (<tr key={i}>{r.map((c, j) => <td key={j} className={`align-top px-3 py-2 ${isIdentity ? '' : 'border border-black'}`} style={isIdentity ? { border: 'none' } : { border: '1px solid black' }}>{parseFormattedText(c.trim())}</td>)}</tr>))}</tbody>
              </table>
            </div>
          );
        }
        currentTable = [];
      }
      inTable = false;
    };

    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.startsWith('|')) { 
        inTable = true; 
        currentTable.push(trimmed.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1)); 
      } else { 
        if (inTable) flushTable(idx); 
        if (trimmed !== '') {
          const isSectionHeader = /^[I|V|X|0-9]+\.\s[A-Z\s]+$/.test(trimmed);
          if (isSectionHeader) {
            elements.push(<div key={idx} className="font-bold text-[12.5px] mt-6 mb-3 border-b-2 border-black uppercase tracking-wider Museum-Text">{parseFormattedText(trimmed)}</div>);
          } else {
            elements.push(<div key={idx} style={{ paddingLeft: '5px', marginBottom: '6px', color: 'black', fontSize: '11px' }}>{parseFormattedText(trimmed)}</div>);
          }
        } 
      }
    });

    if (inTable) flushTable(lines.length);
    return elements;
  };

  return (
    <div className="animate-in fade-in duration-700">
      <BlockingOverlay isVisible={isLoading} text="Menyusun Soal..." isUnlocked={isUnlocked} />

      <ProRequirementNotice 
        isOpen={proNotice.show}
        onClose={() => setProNotice({...proNotice, show: false})}
        featureName={proNotice.feature}
        benefitDesc={proNotice.benefit}
        title={proNotice.title}
        deviceId={myDeviceId}
        canClaimBonus={proNotice.canClaimBonus}
        onShareBonus={handleClaimBonus}
      />

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
        <div className="lg:col-span-5 space-y-6 no-print sticky top-10">
          <div className="rounded-[3rem] shadow-xl overflow-hidden border-4 border-yellow-400 bg-white">
            <div className="flex bg-yellow-50">{(['identity', 'structure', 'topics'] as const).map(tab => (<button key={tab} onClick={() => setActiveFormTab(tab)} className={`flex-1 py-4 text-xs font-black uppercase tracking-widest transition-all relative Museum-Text active:scale-95 ${activeFormTab === tab ? 'text-blue-600' : 'text-slate-400 hover:text-blue-400'}`}>{activeFormTab === tab && <div className="absolute bottom-0 left-0 right-0 h-1.5 bg-blue-500"></div>}{tab === 'identity' ? 'IDENTITAS' : tab === 'structure' ? 'STRUKTUR' : 'MATERI'}</button>))}</div>
            <div className="p-7">
              {activeFormTab === 'identity' && (<div className="space-y-5 animate-in fade-in duration-300"><div className="space-y-1.5"><label className="text-[11px] font-bold uppercase text-slate-500 ml-1">Jenjang</label><select value={formData.jenjang} onChange={e => setFormData({...formData, jenjang: e.target.value})} className="w-full input-futuristic bg-white px-5 py-3 text-sm font-semibold"><option>SD Sederajat</option><option>SMP Sederajat</option><option>SMA Sederajat</option><option>Perguruan Tinggi</option><option>Profesional</option></select></div><div className="space-y-1.5"><label className="text-[11px] font-bold uppercase text-slate-500 ml-1">Institusi (Opsional)</label><input value={formData.sekolah} onChange={e => setFormData({...formData, sekolah: e.target.value})} className="w-full input-futuristic bg-white px-5 py-3 text-sm font-semibold" placeholder="Contoh: SDN 1 Mentari" /></div><div className="space-y-1.5"><label className="text-[11px] font-bold uppercase text-slate-500 ml-1">Judul Asesmen <span className="text-red-500">*</span></label><input value={formData.judulAsesmen} onChange={e => setFormData({...formData, judulAsesmen: e.target.value})} className="w-full input-futuristic bg-white px-5 py-3 text-sm font-semibold" placeholder="Sumatif Akhir Semester" /></div><div className="grid grid-cols-2 gap-4"><div className="space-y-1.5"><label className="text-[11px] font-bold uppercase text-slate-500 ml-1">Mapel</label><input value={formData.mataPelajaran} onChange={e => setFormData({...formData, mataPelajaran: e.target.value})} className="w-full input-futuristic bg-white px-5 py-3 text-sm font-semibold" placeholder="IPAS" /></div><div className="space-y-1.5"><label className="text-[11px] font-bold uppercase text-slate-500 ml-1">Kelas/Smt</label><input value={formData.kelasSemester} onChange={e => setFormData({...formData, kelasSemester: e.target.value})} className="w-full input-futuristic bg-white px-5 py-3 text-sm font-semibold" placeholder="IV / 1" /></div></div></div>)}
              {activeFormTab === 'structure' && (<div className="space-y-5 animate-in fade-in duration-300"><div className="p-6 rounded-3xl border-4 border-blue-50 flex flex-col gap-3 bg-blue-50/50"><div className="flex justify-between items-center"><span className="text-[11px] font-black uppercase text-blue-700 Museum-Text">Target Soal</span><input type="number" value={formData.jumlahSoalTotal} onChange={e => setFormData({...formData, jumlahSoalTotal: e.target.value})} className="w-24 rounded-xl px-3 py-1.5 text-center font-bold bg-white border-2 border-blue-200 text-blue-600" /></div><div className="flex justify-between items-center pt-2 border-t-2 border-blue-100"><span className="text-[11px] font-bold text-slate-400 uppercase">Input Saat Ini:</span><span className={`text-2xl font-black ${isSoalMatching ? 'text-green-500' : 'text-red-400'}`}>{totalCalculatedSoal} / {formData.jumlahSoalTotal}</span></div></div><div className="grid grid-cols-2 gap-3">{formData.formats.map((f, i) => (<div key={f.type} className={`p-3 rounded-2xl border-2 transition-all ${parseInt(f.count) > 0 ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-white border-slate-200 opacity-60'}`}><label className="text-[10px] font-black uppercase mb-1.5 block truncate Museum-Text">{f.type}</label><input type="number" value={f.count} onChange={e => { const nf = [...formData.formats]; nf[i].count = e.target.value; setFormData({...formData, formats: nf})}} className={`w-full bg-transparent border-none p-0 text-xl font-black focus:outline-none ${parseInt(f.count) > 0 ? 'text-white' : 'text-slate-400'}`} /></div>))}</div></div>)}
              {activeFormTab === 'topics' && (<div className="space-y-5 animate-in fade-in duration-300"><div className="p-5 rounded-2xl border-4 border-green-50 bg-green-50/30 flex justify-between items-center"><span className="text-[11px] font-black uppercase text-green-700 Museum-Text">Total Bobot</span><div className={`px-6 py-2 rounded-xl text-xl font-black ${isWeightMatching ? 'text-green-600 bg-white' : 'text-red-500 bg-red-50'}`}>{totalWeight}%</div></div><div className="space-y-3"><div className="flex items-center justify-between ml-1"><label className="text-[11px] font-bold uppercase text-slate-500">Daftar Materi Pokok</label><button onClick={() => setFormData({...formData, topics: [...formData.topics, {materi: '', bobot: '0'}]})} className="text-[10px] font-black uppercase text-blue-600 hover:underline">+ Tambah Baris</button></div>{formData.topics.map((t, i) => (<div key={i} className="flex gap-3 animate-in slide-in-from-left-2 duration-300"><input value={t.materi} onChange={e => { const nt = [...formData.topics]; nt[i].materi = e.target.value; setFormData({...formData, topics: nt})}} className="flex-grow input-futuristic bg-white px-5 py-2.5 text-sm font-bold" placeholder="Materi..." /><div className="relative w-24"><input type="number" value={t.bobot} onChange={e => { const nt = [...formData.topics]; nt[i].bobot = e.target.value; setFormData({...formData, topics: nt})}} className="w-full input-futuristic bg-white px-3 py-2.5 text-sm font-black text-center" /><span className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-bold text-slate-300">%</span></div>{formData.topics.length > 1 && (<button onClick={() => { const nt = formData.topics.filter((_, idx) => idx !== i); setFormData({...formData, topics: nt})}} className="w-10 h-10 rounded-xl bg-red-50 text-red-500 flex items-center justify-center border-2 border-red-100 transition-all active:scale-90"><i className="fas fa-trash-alt text-xs"></i></button>)}</div>))}</div></div>)}
            </div>
            <div className="p-7 pt-0">
               <div className="flex gap-4">
                  {activeFormTab !== 'identity' && (
                    <button onClick={() => { if(activeFormTab === 'structure') setActiveFormTab('identity'); else setActiveFormTab('structure'); }} className="flex-1 py-3.5 rounded-2xl bg-slate-100 text-slate-500 font-black uppercase text-xs hover:bg-slate-200 transition-all">Kembali</button>
                  )}
                  <button 
                    onClick={() => { if(activeFormTab === 'identity') setActiveFormTab('structure'); else if(activeFormTab === 'structure') setActiveFormTab('topics'); else handleGenerate(); }} 
                    disabled={isValidating}
                    className={`flex-[2] py-4 font-bold rounded-2xl Museum-Text uppercase text-sm joyful-shadow bg-blue-600 text-white hover:bg-blue-700 active:scale-95 transition-all`}
                  >
                    {activeFormTab === 'topics' ? (isLoading ? 'Menyusun...' : 'Buat Asesmen') : 'Selanjutnya'}
                  </button>
               </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-7" ref={resultRef}>
          {!result && !isLoading && (
            <div className="h-full min-h-[600px] flex flex-col items-center justify-center bg-white/50 border-4 border-dashed border-yellow-200 rounded-[3rem] p-20 text-center">
              <div className="w-32 h-32 bg-yellow-50 rounded-full flex items-center justify-center mb-10"><i className="fas fa-file-invoice text-yellow-200 text-6xl"></i></div>
              <h3 className="text-xl font-bold text-yellow-300 uppercase Museum-Text">NASKAH KOSONG</h3>
            </div>
          )}
          {isLoading && <AssemblyLoader />}
          {result && (
            <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border-4 border-yellow-400 flex flex-col h-full animate-in zoom-in">
               <div className="p-6 bg-yellow-400 flex flex-wrap gap-4 justify-center no-print">
                  <button onClick={() => { navigator.clipboard.writeText(result); alert("Disalin!"); }} className={`px-6 py-3 text-xs font-bold rounded-xl bg-white text-blue-600 uppercase joyful-shadow`}><i className={`fas fa-copy mr-2`}></i> Salin Data</button>
                  <button onClick={handleDownloadDoc} className="px-6 py-3 text-xs font-bold bg-white text-blue-600 rounded-xl uppercase joyful-shadow"><i className="fas fa-file-word mr-2"></i> Word</button>
                  <button onClick={() => window.print()} className="px-6 py-3 text-xs font-bold bg-white text-blue-600 rounded-xl uppercase joyful-shadow"><i className="fas fa-print mr-2"></i> Cetak</button>
               </div>
               <div className="bg-slate-50 p-8 md:p-16 overflow-auto flex-grow">
                  <div ref={printAreaRef} className="bg-white shadow-xl mx-auto w-full p-[15mm] text-black rounded-sm min-h-[1000px] document-body printable-area">
                    {renderContent(result)}
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default RakitAIPortal;

import React, { useState, useRef } from 'react';
import { TeacherToolType, TeacherSettings, VisualDesign } from '../types';
import { generateTeacherTool } from '../services/teacherToolsService';
import { BlockingOverlay, ProRequirementNotice } from './SharedUI';

const GuruToolboxPortal: React.FC<{ isUnlocked: boolean, myDeviceId?: string, setGlobalBusy: (b: boolean) => void, settings: TeacherSettings }> = ({ isUnlocked, myDeviceId, setGlobalBusy, settings }) => {
  const [activeTool, setActiveTool] = useState<TeacherToolType>('lkpd');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [showProNotice, setShowProNotice] = useState(false);

  const resultRef = useRef<HTMLDivElement>(null);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const [materi, setMateri] = useState('');
  const [kelas, setKelas] = useState('Kelas 4 SD');
  const [phase, setPhase] = useState('Fase B (Kelas 3-4)');
  const [sourceText, setSourceText] = useState('');

  const performGeneration = async () => {
    if (!materi.trim() && activeTool !== 'simplifier') return alert("Mohon isi nama materi!");
    if (activeTool === 'simplifier' && !sourceText.trim()) return alert("Mohon masukkan teks asli!");

    setIsLoading(true);
    setGlobalBusy(true);
    setResult(null);

    try {
      const data = { 
        materi, 
        kelas, 
        phase, 
        text: sourceText,
        sekolah: settings.schoolName || 'Sekolah Mentari',
        guru: settings.teacherName || 'Guru Pengampu'
      };
      const res = await generateTeacherTool(activeTool, data);
      setResult(res.text);
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
    } catch (e) {
      alert("Gagal memproses AI.");
    } finally {
      setIsLoading(false);
      setGlobalBusy(false);
    }
  };

  const handleGenerate = () => {
    if (!isUnlocked) {
        setShowProNotice(true);
        return;
    }
    performGeneration();
  };

  const handleDownloadDoc = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><style>body { font-family: 'Arial', sans-serif; font-size: 11pt; } table { border-collapse: collapse; width: 100%; margin-bottom: 10px; } td, th { border: 1px solid #ddd; padding: 6pt; }</style></head><body>";
    const footer = "</body></html>";
    const blob = new Blob(['\ufeff', header + content + footer], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Dokumen_AI_${materi.replace(/\s+/g, '_')}.doc`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleDownloadHtml = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const fullHtml = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <title>Hasil Generator Mentari AI</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <style>
          @media print { .no-print { display: none; } body { padding: 0; } }
          body { background-color: #f8fafc; padding: 40px; font-family: sans-serif; }
          .container { background: white; padding: 40px; border-radius: 8px; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); max-width: 800px; margin: auto; border: 1px solid #e2e8f0; }
        </style>
      </head>
      <body>
        <div class="no-print mb-8 text-center">
          <button onclick="window.print()" style="background:#2563eb; color:white; padding:10px 25px; border-radius:8px; border:none; cursor:pointer; font-weight:bold; font-size:14px;">CETAK DOKUMEN</button>
        </div>
        <div class="container">
          ${content}
        </div>
      </body>
      </html>
    `;
    const blob = new Blob([fullHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Cetak_AI_${materi.replace(/\s+/g, '_')}.html`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const renderCleanDocument = (text: string) => {
    const lines = text.split('\n');
    const elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];
    let inTable = false;

    const flushTable = (idx: number) => {
      if (currentTable.length > 0) {
        let filteredTable = currentTable.filter(row => {
          const rowText = row.join('').trim();
          return rowText !== '' && !rowText.includes('-') && !rowText.match(/^[:\-\s|]+$/);
        });

        filteredTable = filteredTable.filter(row => {
            const firstCell = row[0]?.trim().toLowerCase() || "";
            const secondCell = row[1]?.trim().toLowerCase() || "";
            const isForbiddenHeader = firstCell === "nomor" || firstCell === "no" || secondCell === "deskripsi" || secondCell === "pertanyaan" || secondCell === "materi";
            return !isForbiddenHeader;
        });

        if (filteredTable.length > 0) {
          const isHeaderKop = filteredTable.length <= 5 && filteredTable[0].length <= 2;
          elements.push(
            <div key={`tbl-${idx}`} className={`mb-6 overflow-x-auto ${isHeaderKop ? 'bg-slate-50 rounded-2xl p-5 border-2 border-indigo-100' : 'border border-slate-200'}`}>
              <table className="w-full border-collapse text-[12px] text-slate-800">
                <tbody>
                  {filteredTable.map((r, i) => (
                    <tr key={i} className={!isHeaderKop ? "border-b border-slate-100" : ""}>
                      {r.map((c, j) => (
                          <td key={j} className={`${isHeaderKop ? 'border-none py-1.5' : 'border-none p-3'} align-top font-bold uppercase`}>
                              {c.trim()}
                          </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        currentTable = [];
      }
      inTable = false;
    };

    let numberedListBuffer: string[][] = [];
    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.includes('-') || trimmed.match(/^[:\-\s|]+$/)) return;
      const numberedMatch = trimmed.match(/^(\d+)\.\s+(.*)/);
      if (numberedMatch) {
          numberedListBuffer.push([numberedMatch[1], numberedMatch[2]]);
          return;
      } else if (numberedListBuffer.length > 0) {
          const listToRender = [...numberedListBuffer];
          elements.push(
            <div key={`list-${idx}`} className="mb-6 bg-white rounded-2xl border border-slate-100 overflow-hidden">
               <table className="w-full border-collapse text-[12px] text-slate-700">
                  <tbody>
                    {listToRender.map((row, lIdx) => (
                      <tr key={lIdx} className="border-b border-slate-50 last:border-0">
                        <td className="w-10 p-3 font-black text-indigo-600 bg-indigo-50/30 text-center align-top">{row[0]}</td>
                        <td className="p-3 font-semibold uppercase align-top">{row[1]}</td>
                      </tr>
                    ))}
                  </tbody>
               </table>
            </div>
          );
          numberedListBuffer = [];
      }
      if (trimmed.startsWith('|')) {
        inTable = true;
        currentTable.push(trimmed.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1));
      } else {
        if (inTable) flushTable(idx);
        if (trimmed === '') return;
        const isHeading = (trimmed.length < 60 && !trimmed.includes(':') && !trimmed.endsWith('.')) || trimmed === trimmed.toUpperCase();
        if (isHeading) {
          elements.push(<div key={idx} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl mb-5 shadow-lg Museum-Text font-black uppercase text-sm tracking-widest text-center border-b-4 border-indigo-800">{trimmed}</div>);
        } else {
          elements.push(<p key={idx} className="mb-4 leading-relaxed text-sm text-slate-700 font-bold uppercase tracking-tight">{trimmed}</p>);
        }
      }
    });
    if (inTable) flushTable(lines.length);
    return elements;
  };

  const tools = [
    { id: 'lkpd', label: 'Generator LKPD', icon: 'fa-file-signature' },
    { id: 'summary', label: 'Ringkasan Materi', icon: 'fa-book-open-reader' },
    { id: 'rubric', label: 'Rubrik Penilaian', icon: 'fa-table-list' },
    { id: 'simplifier', label: 'Penyederhana Teks', icon: 'fa-wand-magic-sparkles' }
  ];

  return (
    <div className="animate-in fade-in duration-700 space-y-8">
      <BlockingOverlay isVisible={isLoading} text="AI Sedang Merakit LKPD..." isUnlocked={isUnlocked} />

      <ProRequirementNotice 
        isOpen={showProNotice} 
        onClose={() => setShowProNotice(false)} 
        featureName="Peralatan Administrasi Guru" 
        benefitDesc="Dapatkan akses untuk merakit dokumen administrasi hari ini dengan membagikan aplikasi Mentari ke grup WhatsApp Guru Anda." 
        deviceId={myDeviceId}
        canClaimBonus={!isUnlocked}
        onShareBonus={() => { setShowProNotice(false); performGeneration(); }}
      />

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-4 space-y-6 sticky top-24 no-print">
          <div className="bg-white rounded-[3rem] p-5 shadow-xl border-4 border-indigo-100">
             <div className="flex flex-col gap-2">
                {tools.map(tool => (
                  <button key={tool.id} onClick={() => { setActiveTool(tool.id as any); setResult(null); }} className={`flex items-center gap-4 p-5 rounded-[2rem] transition-all active:scale-95 text-left ${activeTool === tool.id ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${activeTool === tool.id ? 'bg-white/20' : 'bg-white shadow-sm'}`}><i className={`fas ${tool.icon}`}></i></div>
                    <div><span className="text-[10px] font-black uppercase tracking-widest block leading-none">{tool.label}</span><span className={`text-[8px] font-bold uppercase opacity-60 mt-1 block`}>Asisten Cerdas Guru</span></div>
                  </button>
                ))}
             </div>
          </div>
          <div className="bg-white rounded-[3rem] p-8 shadow-xl border-4 border-indigo-100 space-y-5">
             <h4 className="text-xs font-black uppercase text-indigo-600 Museum-Text mb-4 tracking-tighter">Konfigurasi AI</h4>
             <div className="space-y-4">
                {activeTool === 'simplifier' ? (
                  <>
                    <textarea value={sourceText} onChange={e => setSourceText(e.target.value)} className="w-full input-futuristic px-5 py-3 h-40 resize-none text-xs" placeholder="Tempel teks asli..." />
                    <select value={phase} onChange={e => setPhase(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold uppercase">
                       <option>Fase B (Kelas 3-4)</option><option>Fase A (Kelas 1-2)</option><option>Fase C (Kelas 5-6)</option>
                    </select>
                  </>
                ) : (
                  <>
                    <input value={materi} onChange={e => setMateri(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold uppercase" placeholder="Nama Materi..." />
                    <input value={kelas} onChange={e => setKelas(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold uppercase" placeholder="Kelas 4 SD" />
                  </>
                )}
             </div>
             <button onClick={handleGenerate} disabled={isLoading} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-3">{isLoading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-microchip"></i>} RAKIT DOKUMEN AI</button>
          </div>
        </div>
        <div className="lg:col-span-8 h-full" ref={resultRef}>
          {!result ? (
            <div className="w-full min-h-[600px] border-4 border-dashed border-indigo-200 rounded-[4rem] flex flex-col items-center justify-center p-16 text-center bg-white/50">
               <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mb-8"><i className="fas fa-folder-open text-5xl text-indigo-200"></i></div>
               <h3 className="text-xl font-black uppercase text-indigo-300 Museum-Text tracking-widest">Ruang Kerja AI</h3>
               <p className="mt-4 text-[10px] font-black uppercase text-slate-300 leading-loose tracking-[0.2em]">Data siap diolah menjadi LKPD profesional.</p>
            </div>
          ) : (
            <div className="bg-white rounded-[3.5rem] shadow-2xl border-4 border-indigo-600 overflow-hidden flex flex-col animate-in zoom-in duration-500">
               <div className="p-6 bg-indigo-600 flex flex-wrap gap-3 justify-center no-print">
                  <button onClick={() => { navigator.clipboard.writeText(result); alert("Teks disalin!"); }} className="px-6 py-3 bg-white text-indigo-600 rounded-xl font-black uppercase text-[9px] hover:bg-indigo-50 transition-all flex items-center gap-2 shadow-sm"><i className="fas fa-copy"></i> SALIN DATA</button>
                  <button onClick={handleDownloadHtml} className="px-6 py-3 bg-white text-emerald-600 rounded-xl font-black uppercase text-[9px] hover:bg-emerald-50 transition-all flex items-center gap-2 shadow-sm"><i className="fas fa-file-code"></i> FILE CETAK (HTML)</button>
                  <button onClick={handleDownloadDoc} className="px-6 py-3 bg-white text-indigo-600 rounded-xl font-black uppercase text-[9px] hover:bg-indigo-50 transition-all flex items-center gap-2 shadow-sm"><i className="fas fa-file-word"></i> WORD</button>
               </div>
               <div className="bg-slate-50 p-8 md:p-14 overflow-auto max-h-[900px]">
                  <div ref={printAreaRef} className="bg-white shadow-lg mx-auto w-full p-10 md:p-16 text-black rounded-sm min-h-[1000px] document-body printable-area">
                    {renderCleanDocument(result)}
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

