import React, { useState, useRef } from 'react';
import { MediaToolType, VisualDesign, TeacherSettings } from '../types';
import { generateCreativeMedia } from '../services/creativeMediaService';
import { generateVisualLayout } from '../services/teacherToolsService';
import { BlockingOverlay, ProRequirementNotice } from './SharedUI';

const MediaKreatifPortal: React.FC<{ isUnlocked: boolean, myDeviceId?: string, setGlobalBusy: (b: boolean) => void, settings: TeacherSettings }> = ({ isUnlocked, myDeviceId, setGlobalBusy, settings }) => {
  const [activeTool, setActiveTool] = useState<MediaToolType>('lyrics');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [visualDesign, setVisualDesign] = useState<VisualDesign | null>(null);
  const [showProNotice, setShowProNotice] = useState(false);

  const [materi, setMateri] = useState('');
  const [kelas, setKelas] = useState('Kelas 4 SD');
  const [tone, setTone] = useState('Pelangi-Pelangi');
  const [sourceText, setSourceText] = useState('');

  const resultRef = useRef<HTMLDivElement>(null);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const performGeneration = async () => {
    if (!materi.trim()) return alert("Mohon isi judul materi!");
    if (activeTool === 'mindmap' && !sourceText.trim()) return alert("Mohon isi detail materi!");

    setIsLoading(true);
    setGlobalBusy(true);
    setResult(null);
    setVisualDesign(null);

    try {
      const data = { 
        materi, 
        kelas, 
        tone, 
        text: sourceText,
        sekolah: settings.schoolName || 'Sekolah Mentari',
        guru: settings.teacherName || 'Guru Kreatif'
      };
      const res = await generateCreativeMedia(activeTool, data);
      setResult(res.text);
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
    } catch (e) {
      alert("Gagal memproses media kreatif.");
    } finally {
      setIsLoading(false);
      setGlobalBusy(false);
    }
  };

  const handleGenerate = () => {
    if (!isUnlocked) {
        setShowProNotice(true);
        return;
    }
    performGeneration();
  };

  const handleCanvaMagic = () => {
    if (!result) return;
    const cleanContent = result.replace(/\|/g, ' ').replace(/\n\n+/g, '\n').trim();
    const promptCanva = `
      TASK: Create a professional educational ${activeTool === 'lyrics' ? 'Song Sheet Poster' : 'Educational Mind Map'} for ${materi.toUpperCase()}.
      SCHOOL NAME: ${settings.schoolName || 'Sekolah Mentari'}
      PRIMARY TEXT CONTENT TO USE (COPY EXACTLY, NO TYPOS):
      ---
      ${cleanContent.substring(0, 1000)}
      ---
      VISUAL STYLE: High-Quality Modern Educational Graphic, Minimalist, Clean Typography, Academic Aesthetic.
      INSTRUCTION: Use ONLY the provided text. Ensure all words are spelled correctly as written in the content block above.
    `.trim();

    navigator.clipboard.writeText(promptCanva);
    alert("🚀 PROMPT MAGIC DESIGN DISALIN!\n\nLangkah:\n1. Setelah Anda klik OK maka Canva akan terbuka,\n2. CTRL+V pada kolom Magic Design,\n3. Klik Generate (tanda panah kanan).");
    window.open('https://www.canva.com/ai', '_blank');
  };

  const handleDownloadHtml = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const fullHtml = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <title>Media Kreatif - ${materi}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <style>
          @media print { .no-print { display: none; } body { padding: 0; } }
          body { background-color: #fff1f2; padding: 40px; font-family: sans-serif; }
