                    <option value="lyrics">Lirik Lagu Edukasi</option>
                    <option value="mindmap">Mind Map Tekstual</option>
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Materi Utama</label>
                  <input value={materi} onChange={e => setMateri(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold" placeholder="Misal: Siklus Air" />
                </div>
                {activeTool === 'lyrics' ? (
                   <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-2">Nada Lagu</label><input value={tone} onChange={e => setTone(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold" /></div>
                ) : (
                   <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-2">Detail Materi</label><textarea value={sourceText} onChange={e => setSourceText(e.target.value)} className="w-full input-futuristic px-5 py-3 h-32 resize-none text-xs" /></div>
                )}
             </div>
             <button onClick={handleGenerate} className="w-full py-4 bg-rose-500 text-white rounded-2xl font-black uppercase text-xs joyful-shadow">RAKIT MEDIA</button>
          </div>
        </div>
        <div className="lg:col-span-8 h-full" ref={resultRef}>
          {!result ? (
            <div className="w-full min-h-[600px] border-4 border-dashed border-rose-200 rounded-[4rem] flex flex-col items-center justify-center p-16 text-center bg-white/50">
               <div className="w-24 h-24 bg-rose-50 rounded-full flex items-center justify-center mb-8"><i className="fas fa-music text-5xl text-rose-200"></i></div>
               <h3 className="text-xl font-black uppercase text-rose-300 Museum-Text">Studio Kreatif</h3>
