    const normalizedStudents = students.map(s => ({ ...s, id: (s.id || '').toString().trim() }));
    const normalizedGrades = (grades || []).map(g => ({ studentId: (g.studentId || '').toString().trim(), subject: (g.subject || '').toString().trim().toLowerCase(), score: Number(g.score || 0), date: g.date || new Date().toISOString() }));
