          </div>
          <div className="w-64 h-1.5 bg-slate-800 rounded-full overflow-hidden relative border border-white/5">
             <div className="h-full bg-blue-50 shadow-[0_0_15px_rgba(59,130,246,1)] animate-loading"></div>
          </div>
