      objective: 'Memperkuat iman dan rasa syukur melalui refleksi alam.',
      skills: ['Religius', 'Refleksi'],
      difficulty: 'Mudah',
      duration: '5 Menit',
      placeholder: 'Keajaiban Alam (misal: Terumbu Karang)' 
    },
    { 
      id: 'budaya', 
