                        </div>
                        <div>
                            <h3 className="text-2xl font-black text-blue-900 Museum-Text uppercase leading-none tracking-tight">{card?.title}</h3>
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">{card?.dimensi}</p>
                        </div>
                      </div>

                      <div className={`mb-10 p-6 bg-${card?.color}-50 border-2 border-${card?.color}-100 rounded-3xl animate-in fade-in slide-in-from-top-4 duration-700 shadow-inner`}>
                         <h4 className={`text-[10px] font-black uppercase text-${card?.color}-600 mb-3 tracking-[0.2em] flex items-center gap-2`}>
                            <i className="fas fa-lightbulb"></i> Panduan Langkah Misi
                         </h4>
                         <p className="text-[10px] font-bold text-slate-700 uppercase leading-relaxed italic">
                            {card?.instruction}
                         </p>
                      </div>

                      <div className="space-y-6">
                        <div className="relative">
                            <input 
                              value={adventureInput} 
                              onChange={e => setAdventureInput(e.target.value)}
                              className="w-full input-futuristic px-8 py-5 text-lg font-bold text-blue-600 focus:ring-8 focus:ring-blue-500/10 transition-all outline-none border-2 border-slate-100 shadow-inner" 
                              placeholder={card?.placeholder} 
                              autoFocus
                            />
                            <div className="absolute right-6 top-1/2 -translate-y-1/2 opacity-20">
                                <i className="fas fa-keyboard text-xl"></i>
                            </div>
                        </div>
                        <button 
                          onClick={executeAdventure}
                          disabled={isLoading}
                          className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-sm tracking-[0.2em] shadow-xl shadow-blue-600/20 hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center gap-3"
                        >
                          {isLoading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>}
                          {isLoading ? 'Membuka Portal...' : 'Jalankan Misi Dimensi'}
                        </button>
                      </div>
                    </div>
                  );
                })()}
             </div>
          </div>
        )
      )}

      <BlockingOverlay isVisible={isLoading} text="AI Sedang Melukis Duniamu..." onCancel={handleCancelGeneration} isUnlocked={isUnlocked} />

      {adventureResult && (
        <div className="animate-in slide-in-from-bottom-12 duration-700" ref={resultRef}>
          <div className="bg-white rounded-[2.5rem] md:rounded-[4rem] shadow-2xl border-4 md:border-8 border-white overflow-hidden flex flex-col h-[75vh] md:h-[80vh] relative">
            <div className="p-4 md:p-6 bg-white border-b-2 border-slate-50 flex items-center justify-between z-50 shrink-0">
               <div className="flex items-center gap-4">
                  <div className="w-8 h-8 md:w-10 md:h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center text-sm md:text-base"><i className="fas fa-mountain-sun"></i></div>
                  <h4 className="text-xs md:text-sm font-black text-slate-800 Museum-Text uppercase">Portal Petualangan Aktif</h4>
               </div>
               <div className="flex gap-2 md:gap-3">
                  <button onClick={handleFullscreen} className="w-8 h-8 md:w-10 md:h-10 bg-slate-50 shadow-sm rounded-xl text-blue-600 flex items-center justify-center hover:bg-blue-600 hover:text-white transition-all active:scale-90 border border-slate-200" title="Layar Penuh"><i className="fas fa-expand-alt text-xs md:text-sm"></i></button>
                  <button onClick={() => { 
                      if(confirm("Yakin ingin menutup tanpa mengambil hadiah? Kemajuan tidak akan tersimpan.")) {
                          handleCloseAdventure();
                      }
                  }} className="w-8 h-8 md:w-10 md:h-10 bg-slate-50 shadow-sm rounded-xl text-red-500 flex items-center justify-center hover:bg-red-500 hover:text-white transition-all active:scale-90 border border-slate-200" title="Tutup Tanpa Hadiah"><i className="fas fa-times text-xs md:text-sm"></i></button>
               </div>
            </div>

            <div className="flex-grow w-full bg-slate-50 relative overflow-hidden" ref={iframeContainerRef}>
              <iframe 
                srcDoc={adventureResult}
                className="w-full h-full border-none shadow-inner"
                title="Adventure Result"
              />
            </div>

