    let currentTable: string[][] = [];
    let inTable = false;

    const flushTable = (idx: number) => {
      if (currentTable.length > 0) {
        elements.push(
          <div key={`tbl-${idx}`} className="mb-8 p-6 bg-emerald-50/50 rounded-[2.5rem] border-2 border-emerald-100 shadow-sm">
