    const newWork: AIWork = {
        id: Date.now().toString(),
        title: ADVENTURE_CARDS.find(c => c.id === activeAdventure)?.title || 'Karya AI',
        type: activeAdventure,
        content: adventureResult,
        date: new Date().toLocaleDateString()
    };

    const newExp = profile.exp + 50;
    let newLevel = profile.level;
    if (newExp >= profile.level * 200) {
        newLevel += 1;
    }

    let nextCompletedIds = [...profile.completedAdventureIds];
    if (!nextCompletedIds.includes(activeAdventure)) {
        nextCompletedIds.push(activeAdventure);
    }

    onUpdateProfile({
        ...profile,
        exp: newExp,
        level: newLevel,
        coins: profile.coins + 20,
        lastAdventureDate: today,
        completedAdventureIds: nextCompletedIds,
        dailyTasks: profile.dailyTasks.includes('adventure') ? profile.dailyTasks : [...profile.dailyTasks, 'adventure'],
        aiWorks: [newWork, ...(profile.aiWorks || [])].slice(0, 10)
    });

    handleCloseAdventure();
  };

  const toggleFullscreen = () => {
    if (adventureContainerRef.current) {
        if (!document.fullscreenElement) {
            adventureContainerRef.current.requestFullscreen().catch(err => {
                alert(`Error attempting to enable full-screen mode: ${err.message}`);
            });
        } else {
            document.exitFullscreen();
        }
    }
  };

  const AdventureCard: React.FC<{ card: typeof ADVENTURE_CARDS[0] }> = ({ card }) => {
    const isCompleted = profile.completedAdventureIds.includes(card.id);
    const isCore = corePillars.some(c => c.id === card.id);
    const isExtra = explorationAdventures.some(c => c.id === card.id);
    const isInCycleLock = (isCore && isCompleted && !isCoreFullyDone) || (isExtra && isCompleted && !isExtraFullyDone);
    const today = new Date().toLocaleDateString();
    const hasDoneToday = profile.lastAdventureDate === today;

    return (
      <div className="h-full relative overflow-visible">
        <button 
          onClick={() => handleStartAdventure(card.id)}
          className={`group relative flex flex-col w-full h-full bg-white p-8 rounded-[3.5rem] border-4 shadow-[0_15px_40px_-15px_rgba(0,0,0,0.1)] transition-all duration-500 overflow-hidden active:scale-95 text-left ${hasDoneToday || isInCycleLock ? 'grayscale border-slate-100' : `border-slate-50 hover:shadow-2xl hover:-translate-y-2 hover:border-${card.color}-200`}`}
        >
          <div className="flex justify-between items-start mb-6 relative z-10">
            <div className="flex flex-col gap-1.5">
              <div className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-[0.1em] bg-${card.color}-50 text-${card.color}-600 border border-${card.color}-100 w-fit`}>
                {card.dimensi}
              </div>
              {isCompleted && (
                <div className="px-3 py-1 rounded-full text-[8px] font-black uppercase bg-emerald-50 text-emerald-600 border border-emerald-100 flex items-center gap-1 w-fit tracking-wider">
                   <i className="fas fa-check-circle"></i> Selesai
                </div>
              )}
            </div>
            <div className="flex items-center gap-1.5 text-slate-400">
              <i className="fas fa-bolt text-[9px] text-yellow-400"></i>
              <span className="text-[9px] font-bold uppercase tracking-widest">{card.duration}</span>
            </div>
          </div>

          <div className="flex items-center gap-4 mb-6 relative z-10">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center bg-${card.color}-500 text-white text-2xl shadow-lg transform group-hover:rotate-6 transition-all duration-500`}>
              <i className={`fas ${card.icon}`}></i>
            </div>
            <div>
              <h4 className="text-sm font-black text-slate-800 Museum-Text uppercase leading-none tracking-tight">{card.title}</h4>
              <p className="text-[8px] font-black text-slate-400 uppercase tracking-[0.2em] mt-2">Selesai +20 Koin</p>
            </div>
          </div>

          <div className="flex-grow space-y-4 relative z-10 mb-6">
            <p className="text-[10px] font-bold text-slate-500 leading-relaxed uppercase tracking-wide">{card.desc}</p>
            <div className={`p-4 bg-${card.color}-50/50 rounded-2xl border border-${card.color}-100/50`}>
              <span className={`text-[8px] font-black uppercase text-${card.color}-600 tracking-[0.2em] block mb-1.5`}>Misi Karakter</span>
              <p className="text-[9px] font-bold text-slate-600 leading-tight italic">"{card.objective}"</p>
            </div>
          </div>

          <div className="flex flex-wrap gap-2 pt-4 border-t border-slate-50 relative z-10">
            {card.skills.map(skill => (
              <span key={skill} className="px-3 py-1 bg-slate-100 text-slate-500 rounded-lg text-[7px] font-black uppercase tracking-wider">
                #{skill}
              </span>
            ))}
          </div>

          {(hasDoneToday || isInCycleLock) && (
              <div className="absolute inset-0 bg-slate-100/40 backdrop-blur-[2px] z-20 flex flex-col items-center justify-center p-6 text-center animate-in fade-in duration-300">
                   <div className="w-14 h-14 bg-white rounded-3xl flex items-center justify-center shadow-2xl mb-4 border-2 border-slate-100">
                      <i className={`fas ${isInCycleLock ? 'fa-lock text-amber-400' : 'fa-battery-empty text-slate-300'} text-2xl`}></i>
                   </div>
                   <p className="text-[10px] font-black text-slate-600 uppercase tracking-[0.2em] px-4 leading-relaxed">
                      {isInCycleLock ? 'Selesaikan Misi Lain Dulu' : 'Energi Petualang Habis'}
                   </p>
                   {isInCycleLock && <span className="text-[7px] font-black text-amber-600 uppercase mt-2 tracking-widest bg-amber-50 px-2 py-0.5 rounded-full border border-amber-100">Fokus Keseimbangan</span>}
              </div>
          )}

          <div className={`absolute -right-6 -bottom-6 w-32 h-32 bg-${card.color}-50 rounded-full opacity-50 group-hover:scale-110 transition-all duration-700 pointer-events-none`}></div>
        </button>
      </div>
    );
  };

  return (
    <div className="animate-in fade-in duration-700">
      {!activeAdventure ? (
        <div className="space-y-12">
          <div>
            <div className="flex items-center gap-4 mb-6">
               <div className="h-8 w-2 bg-indigo-500 rounded-full shadow-lg shadow-indigo-500/20"></div>
               <h3 className="text-xl font-black text-indigo-900 Museum-Text uppercase tracking-tight">Eksplorasi 8 Dimensi Profil Lulusan</h3>
               <span className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] ml-auto">Progres: {profile.completedAdventureIds.filter(id => corePillars.some(c => c.id === id)).length} / 8</span>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 auto-rows-fr">
              {corePillars.map(card => (
                <AdventureCard key={card.id} card={card} />
              ))}
            </div>
          </div>

          <div>
            <div className="flex items-center gap-4 mb-6">
               <div className="h-8 w-2 bg-rose-500 rounded-full shadow-lg shadow-rose-500/20"></div>
               <h3 className="text-xl font-black text-rose-900 Museum-Text uppercase tracking-tight">Eksplorasi Akademik Tambahan</h3>
               <span className="text-[10px] font-black text-rose-400 uppercase tracking-[0.2em] ml-auto">Progres: {profile.completedAdventureIds.filter(id => explorationAdventures.some(c => c.id === id)).length} / 4</span>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 auto-rows-fr">
              {explorationAdventures.map(card => (
                <AdventureCard key={card.id} card={card} />
              ))}
            </div>
          </div>
        </div>
      ) : (
        !adventureResult && (
          <div className="animate-in slide-in-from-bottom-8 duration-500">
             <div className="max-w-3xl mx-auto bg-white rounded-[3.5rem] p-10 md:p-14 shadow-2xl border-4 border-blue-100 relative">
                <button onClick={() => { setActiveAdventure(null); setAdventureResult(null); }} className="absolute top-8 right-8 text-slate-300 hover:text-red-500 transition-all active:scale-90 z-30"><i className="fas fa-times-circle text-3xl"></i></button>

                {(() => {
                  const card = ADVENTURE_CARDS.find(c => c.id === activeAdventure);
                  return (
                    <div className="relative z-10">
                      <div className="flex items-center gap-6 mb-10">
                        <div className={`w-16 h-16 rounded-3xl flex items-center justify-center text-white text-2xl shadow-xl bg-${card?.color}-500 shrink-0`}>
                            <i className={`fas ${card?.icon}`}></i>
                        </div>
                        <div>
                            <h3 className="text-2xl font-black text-blue-900 Museum-Text uppercase leading-none tracking-tight">{card?.title}</h3>
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">{card?.dimensi}</p>
                        </div>
                      </div>

                      <div className={`mb-10 p-6 bg-${card?.color}-50 border-2 border-${card?.color}-100 rounded-3xl animate-in fade-in slide-in-from-top-4 duration-700 shadow-inner`}>
                         <h4 className={`text-[10px] font-black uppercase text-${card?.color}-600 mb-3 tracking-[0.2em] flex items-center gap-2`}>
                            <i className="fas fa-lightbulb"></i> Panduan Langkah Misi
                         </h4>
                         <p className="text-[10px] font-bold text-slate-700 uppercase leading-relaxed italic">
                            {card?.instruction}
                         </p>
                      </div>

                      <div className="space-y-6">
                        <div className="relative">
                            <input 
                              value={adventureInput} 
                              onChange={e => setAdventureInput(e.target.value)}
                              className="w-full input-futuristic px-8 py-5 text-lg font-bold text-blue-600 focus:ring-8 focus:ring-blue-500/10 transition-all outline-none border-2 border-slate-100 shadow-inner" 
                              placeholder={card?.placeholder} 
                              autoFocus
                            />
                            <div className="absolute right-6 top-1/2 -translate-y-1/2 opacity-20">
                                <i className="fas fa-keyboard text-xl"></i>
                            </div>
                        </div>
                        <button 
                          onClick={executeAdventure}
                          disabled={isLoading}
                          className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-sm tracking-[0.2em] shadow-xl shadow-blue-600/20 hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center gap-3"
                        >
                          {isLoading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>}
                          {isLoading ? 'Membuka Portal...' : 'Jalankan Misi Dimensi'}
                        </button>
                      </div>
                    </div>
                  );
                })()}
             </div>
          </div>
        )
      )}

      <BlockingOverlay isVisible={isLoading} text="AI Sedang Melukis Duniamu..." onCancel={handleCancelGeneration} isUnlocked={isUnlocked} />

      {/* OVERLAY HASIL PETUALANGAN DENGAN BINGKAI STANDAR */}
      {adventureResult && (
        <div ref={adventureContainerRef} className="fixed inset-0 z-[7000] bg-slate-900 flex flex-col h-screen overflow-hidden animate-in zoom-in duration-300">
            {/* Header Bingkai */}
            <div className="bg-indigo-900 p-3 md:p-4 border-b-2 border-indigo-400 flex justify-between items-center z-10 shadow-lg shrink-0">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white border border-indigo-300 shadow-md">
                        <i className="fas fa-mountain-sun text-xl animate-pulse"></i>
                    </div>
                    <div>
                        <h3 className="text-white font-black uppercase text-xs md:text-sm Museum-Text leading-none">Petualangan Aktif</h3>
                        <p className="text-[8px] md:text-[9px] text-indigo-300 font-bold uppercase tracking-widest mt-1">Eksplorasi Dimensi Profil Lulusan</p>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={toggleFullscreen} className="bg-white/10 hover:bg-indigo-700 text-white px-3 md:px-4 py-1.5 md:py-2 rounded-xl transition-all font-black text-[9px] uppercase border border-white/20">
                        <i className="fas fa-expand mr-1.5"></i> Layar Penuh
                    </button>
                    <button onClick={() => { if(confirm("Tutup petualangan tanpa mengambil hadiah?")) handleCloseAdventure(); }} className="bg-red-500/20 hover:bg-red-600 text-red-100 px-3 md:px-4 py-1.5 md:py-2 rounded-xl transition-all font-black text-[9px] uppercase border border-red-400/30">
                        <i className="fas fa-times mr-1.5"></i> Tutup
                    </button>
                </div>
            </div>

            {/* Body Bingkai (Konten) */}
            <div className="flex-grow w-full relative bg-slate-50 overflow-hidden">
                <iframe 
                    ref={iframeRef}
                    srcDoc={adventureResult}
                    className="absolute inset-0 w-full h-full border-none shadow-inner"
                    title="Adventure Content"
                    sandbox="allow-scripts allow-same-origin allow-popups allow-forms"
                />
            </div>

            {/* Footer Bingkai (Area Klaim Hadiah) */}
            <div className="bg-white p-3 md:p-5 border-t-2 border-slate-100 flex flex-col md:flex-row items-center justify-center gap-4 shrink-0">
                {isAdventureFinished ? (
                    <div className="animate-in slide-in-from-bottom-2 duration-500 flex flex-col items-center">
                        <button 
                            onClick={handleClaimReward}
                            disabled={readTimer > 0}
                            className={`px-8 md:px-12 py-3 md:py-3.5 rounded-full font-black uppercase text-[10px] md:text-[11px] tracking-widest shadow-2xl transition-all flex items-center gap-3 md:gap-4 active:scale-95 ${readTimer > 0 ? 'bg-slate-200 text-slate-400 cursor-not-allowed grayscale' : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-emerald-500/30 animate-bounce'}`}
                        >
                            {readTimer > 0 ? (
                                <><i className="fas fa-clock fa-spin"></i> Memproses Misi ({readTimer}s)</>
                            ) : (
                                <><i className="fas fa-check-circle text-base"></i> Ambil Hadiah Petualang</>
                            )}
                        </button>
                        {readTimer === 0 && <p className="text-[8px] font-black text-emerald-500 uppercase mt-2 tracking-widest animate-pulse">Selesaikan Sekarang Untuk +20 Koin & +50 EXP!</p>}
                    </div>
                ) : (
                    <div className="flex items-center gap-4 px-6 py-3 bg-blue-50 border-2 border-blue-100 rounded-2xl animate-pulse">
                        <i className="fas fa-scroll text-blue-600"></i>
                        <span className="text-[9px] md:text-[10px] font-black text-blue-700 uppercase tracking-widest">Selesaikan seluruh narasi petualangan untuk membuka tombol hadiah!</span>
                    </div>
                )}
            </div>
        </div>
      )}
    </div>
  );
};

export default PetualanganPortal;

import React, { useState, useRef, useEffect } from 'react';
import { TeacherToolType, TeacherSettings, VisualDesign } from '../types';
import { generateTeacherTool } from '../services/teacherToolsService';
import { BlockingOverlay, ProRequirementNotice } from './SharedUI';
import { validateUsageCloud, getUsageStatusCloud } from '../services/validationService';

const GuruToolboxPortal: React.FC<{ isUnlocked: boolean, gasUrl?: string, myDeviceId?: string, setGlobalBusy: (b: boolean) => void, settings: TeacherSettings }> = ({ isUnlocked, gasUrl, myDeviceId, setGlobalBusy, settings }) => {
  const [activeTool, setActiveTool] = useState<TeacherToolType>('lkpd');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [isCloudBlocked, setIsCloudBlocked] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [dailyCount, setDailyCount] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`usage_toolbox_v1_${today}`);
    return saved ? parseInt(saved) : 0;
  });

  const [hasBonusToday, setHasBonusToday] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`bonus_toolbox_v1_${today}`);
    return saved === 'true';
  });

  const [proNotice, setProNotice] = useState<{show: boolean, title: string, feature: string, benefit: string, canClaimBonus?: boolean}>({
    show: false, title: '', feature: '', benefit: '', canClaimBonus: false
  });

  const resultRef = useRef<HTMLDivElement>(null);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const [materi, setMateri] = useState('');
  const [kelas, setKelas] = useState('Kelas 4 SD');
  const [phase, setPhase] = useState('Fase B (Kelas 3-4)');
  const [sourceText, setSourceText] = useState('');

  const currentLimit = hasBonusToday ? 1 : 0;

  useEffect(() => {
    const checkCloud = async () => {
      if (!isUnlocked && myDeviceId) {
        setIsValidating(true);
        const isAllowed = await getUsageStatusCloud(myDeviceId, 'Peralatan Guru', currentLimit, gasUrl || "NONE");
        if (!isAllowed) setIsCloudBlocked(true);
        setIsValidating(false);
      }
    };
    checkCloud();
  }, [isUnlocked, myDeviceId, gasUrl, currentLimit]);

  const handleClaimBonus = () => {
    const today = new Date().toLocaleDateString();
    setHasBonusToday(true);
    localStorage.setItem(`bonus_toolbox_v1_${today}`, 'true');
    setProNotice(prev => ({ ...prev, show: false }));
    setIsCloudBlocked(false); 
    alert("🌟 BONUS DIAKTIFKAN!\n\n1 Kesempatan Merakit Dokumen telah terbuka. Silakan klik tombol Rakit Dokumen lagi.");
  };

  const performGeneration = async () => {
    if (!materi.trim() && activeTool !== 'simplifier') return alert("Mohon isi nama materi!");
    if (activeTool === 'simplifier' && !sourceText.trim()) return alert("Mohon masukkan teks asli!");

    setIsLoading(true);
    setGlobalBusy(true);
    setResult(null);

    try {
      if (!isUnlocked && myDeviceId) {
        const isAllowed = await validateUsageCloud(myDeviceId, 'Peralatan Guru', currentLimit, gasUrl || "NONE", dailyCount);
        if (!isAllowed) {
            setIsLoading(false); setGlobalBusy(false); setIsCloudBlocked(true);
            setProNotice({ show: true, title: 'Akses Terbatas', feature: 'Peralatan Administrasi', benefit: 'Gunakan Akun PRO untuk akses tanpa batas harian.', canClaimBonus: !hasBonusToday });
            return;
        }
      }

      const data = { 
        materi, 
        kelas, 
        phase, 
        text: sourceText,
        sekolah: settings.schoolName || 'Sekolah Mentari',
        guru: settings.teacherName || 'Guru Pengampu'
      };
      const res = await generateTeacherTool(activeTool, data);
      setResult(res.text);

      if (!isUnlocked) {
        const today = new Date().toLocaleDateString();
        const newCount = dailyCount + 1;
        setDailyCount(newCount);
        localStorage.setItem(`usage_toolbox_v1_${today}`, newCount.toString());
      }

      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
    } catch (e) {
      alert("Gagal memproses AI.");
    } finally {
      setIsLoading(false);
      setGlobalBusy(false);
    }
  };

  const handleGenerate = () => {
    if (!isUnlocked) {
        if (dailyCount === 0 && !hasBonusToday) {
            setProNotice({ 
                show: true, 
                title: 'Akses Terkunci', 
                feature: 'Peralatan Administrasi', 
                benefit: 'Bapak/Ibu dapat mencoba fitur ini secara GRATIS dengan membagikan aplikasi Mentari terlebih dahulu.',
                canClaimBonus: true 
            });
            return;
        }
        if (dailyCount >= 1 || (isCloudBlocked && !hasBonusToday)) {
            setProNotice({ 
                show: true, 
                title: 'Limit Harian Tercapai', 
                feature: 'Akses Dokumen Berlanjut', 
                benefit: 'Jatah gratis melalui share sudah digunakan. Upgrade ke GURU PRO untuk akses tanpa batas setiap saat.', 
                canClaimBonus: false 
            });
            return;
        }
    }
    performGeneration();
  };

  const handleDownloadDoc = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><style>body { font-family: 'Arial', sans-serif; font-size: 11pt; } table { border-collapse: collapse; width: 100%; margin-bottom: 10px; } td, th { border: 1px solid #ddd; padding: 6pt; }</style></head><body>";
    const footer = "</body></html>";
    const blob = new Blob(['\ufeff', header + content + footer], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Dokumen_AI_${materi.replace(/\s+/g, '_')}.doc`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleDownloadHtml = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const fullHtml = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <title>Hasil Generator Mentari AI</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <style>
          @media print { .no-print { display: none; } body { padding: 0; } }
          body { background-color: #f8fafc; padding: 40px; font-family: sans-serif; }
          .container { background: white; padding: 40px; border-radius: 8px; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); max-width: 800px; margin: auto; border: 1px solid #e2e8f0; }
        </style>
      </head>
      <body>
        <div class="no-print mb-8 text-center">
          <button onclick="window.print()" style="background:#2563eb; color:white; padding:10px 25px; border-radius:8px; border:none; cursor:pointer; font-weight:bold; font-size:14px;">CETAK DOKUMEN</button>
        </div>
        <div class="container">
          ${content}
        </div>
      </body>
      </html>
    `;
    const blob = new Blob([fullHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Cetak_AI_${materi.replace(/\s+/g, '_')}.html`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const renderCleanDocument = (text: string) => {
    const lines = text.split('\n');
    const elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];
    let inTable = false;

    const flushTable = (idx: number) => {
      if (currentTable.length > 0) {
        let filteredTable = currentTable.filter(row => {
          const rowText = row.join('').trim();
          return rowText !== '' && !rowText.includes('-') && !rowText.match(/^[:\-\s|]+$/);
        });

        filteredTable = filteredTable.filter(row => {
            const firstCell = row[0]?.trim().toLowerCase() || "";
            const secondCell = row[1]?.trim().toLowerCase() || "";
            const isForbiddenHeader = firstCell === "nomor" || firstCell === "no" || secondCell === "deskripsi" || secondCell === "pertanyaan" || secondCell === "materi";
            return !isForbiddenHeader;
        });

        if (filteredTable.length > 0) {
          const isHeaderKop = filteredTable.length <= 5 && filteredTable[0].length <= 2;
          elements.push(
            <div key={`tbl-${idx}`} className={`mb-6 overflow-x-auto ${isHeaderKop ? 'bg-slate-50 rounded-2xl p-5 border-2 border-indigo-100' : 'border border-slate-200'}`}>
              <table className="w-full border-collapse text-[12px] text-slate-800">
                <tbody>
                  {filteredTable.map((r, i) => (
                    <tr key={i} className={!isHeaderKop ? "border-b border-slate-100" : ""}>
                      {r.map((c, j) => (
                          <td key={j} className={`${isHeaderKop ? 'border-none py-1.5' : 'border-none p-3'} align-top font-bold uppercase`}>
                              {c.trim()}
                          </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        currentTable = [];
      }
      inTable = false;
    };

    let numberedListBuffer: string[][] = [];
    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.includes('-') || trimmed.match(/^[:\-\s|]+$/)) return;
      const numberedMatch = trimmed.match(/^(\d+)\.\s+(.*)/);
      if (numberedMatch) {
          numberedListBuffer.push([numberedMatch[1], numberedMatch[2]]);
          return;
      } else if (numberedListBuffer.length > 0) {
          const listToRender = [...numberedListBuffer];
          elements.push(
            <div key={`list-${idx}`} className="mb-6 bg-white rounded-2xl border border-slate-100 overflow-hidden">
               <table className="w-full border-collapse text-[12px] text-slate-700">
                  <tbody>
                    {listToRender.map((row, lIdx) => (
                      <tr key={lIdx} className="border-b border-slate-50 last:border-0">
                        <td className="w-10 p-3 font-black text-indigo-600 bg-indigo-50/30 text-center align-top">{row[0]}</td>
                        <td className="p-3 font-semibold uppercase align-top">{row[1]}</td>
                      </tr>
                    ))}
                  </tbody>
               </table>
            </div>
          );
          numberedListBuffer = [];
      }
      if (trimmed.startsWith('|')) {
        inTable = true;
        currentTable.push(trimmed.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1));
      } else {
        if (inTable) flushTable(idx);
        if (trimmed === '') return;
        const isHeading = (trimmed.length < 60 && !trimmed.includes(':') && !trimmed.endsWith('.')) || trimmed === trimmed.toUpperCase();
        if (isHeading) {
          elements.push(<div key={idx} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl mb-5 shadow-lg Museum-Text font-black uppercase text-sm tracking-widest text-center border-b-4 border-indigo-800">{trimmed}</div>);
        } else {
          elements.push(<p key={idx} className="mb-4 leading-relaxed text-sm text-slate-700 font-bold uppercase tracking-tight">{trimmed}</p>);
        }
      }
    });
    if (inTable) flushTable(lines.length);
    return elements;
  };

  const tools = [
    { id: 'lkpd', label: 'Generator LKPD', icon: 'fa-file-signature' },
    { id: 'summary', label: 'Ringkasan Materi', icon: 'fa-book-open-reader' },
    { id: 'rubric', label: 'Rubrik Penilaian', icon: 'fa-table-list' },
    { id: 'simplifier', label: 'Penyederhana Teks', icon: 'fa-wand-magic-sparkles' }
  ];

  return (
    <div className="animate-in fade-in duration-700 space-y-8">
      <BlockingOverlay isVisible={isLoading} text="AI Sedang Merakit LKPD..." isUnlocked={isUnlocked} />

      <ProRequirementNotice 
        isOpen={proNotice.show} 
        onClose={() => setProNotice({...proNotice, show: false})} 
        featureName={proNotice.feature} 
        benefitDesc={proNotice.benefit} 
        deviceId={myDeviceId}
        canClaimBonus={proNotice.canClaimBonus}
        onShareBonus={handleClaimBonus}
      />

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-4 space-y-6 sticky top-24 no-print">
          <div className="bg-white rounded-[3rem] p-5 shadow-xl border-4 border-indigo-100">
             <div className="flex flex-col gap-2">
                {tools.map(tool => (
                  <button key={tool.id} onClick={() => { setActiveTool(tool.id as any); setResult(null); }} className={`flex items-center gap-4 p-5 rounded-[2rem] transition-all active:scale-95 text-left ${activeTool === tool.id ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${activeTool === tool.id ? 'bg-white/20' : 'bg-white shadow-sm'}`}><i className={`fas ${tool.icon}`}></i></div>
                    <div><span className="text-[10px] font-black uppercase tracking-widest block leading-none">{tool.label}</span><span className={`text-[8px] font-bold uppercase opacity-60 mt-1 block`}>Asisten Cerdas Guru</span></div>
                  </button>
                ))}
             </div>
          </div>
          <div className="bg-white rounded-[3rem] p-8 shadow-xl border-4 border-indigo-100 space-y-5">
             <h4 className="text-xs font-black uppercase text-indigo-600 Museum-Text mb-4 tracking-tighter">Konfigurasi AI</h4>
             <div className="space-y-4">
                {activeTool === 'simplifier' ? (
                  <>
                    <textarea value={sourceText} onChange={e => setSourceText(e.target.value)} className="w-full input-futuristic px-5 py-3 h-40 resize-none text-xs" placeholder="Tempel teks asli..." />
                    <select value={phase} onChange={e => setPhase(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold uppercase">
                       <option>Fase B (Kelas 3-4)</option><option>Fase A (Kelas 1-2)</option><option>Fase C (Kelas 5-6)</option>
                    </select>
                  </>
                ) : (
                  <>
                    <input value={materi} onChange={e => setMateri(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold uppercase" placeholder="Nama Materi..." />
                    <input value={kelas} onChange={e => setKelas(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold uppercase" placeholder="Kelas 4 SD" />
                  </>
                )}
             </div>
             <button onClick={handleGenerate} disabled={isLoading || isValidating} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-3">
               {isValidating ? <i className="fas fa-shield-halved fa-spin"></i> : isLoading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-microchip"></i>} 
               {isValidating ? 'VALIDASI...' : 'RAKIT DOKUMEN AI'}
             </button>
          </div>
        </div>
        <div className="lg:col-span-8 h-full" ref={resultRef}>
          {!result ? (
            <div className="w-full min-h-[600px] border-4 border-dashed border-indigo-200 rounded-[4rem] flex flex-col items-center justify-center p-16 text-center bg-white/50">
               <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mb-8"><i className="fas fa-folder-open text-5xl text-indigo-200"></i></div>
               <h3 className="text-xl font-black uppercase text-indigo-300 Museum-Text tracking-widest">Ruang Kerja AI</h3>
               <p className="mt-4 text-[10px] font-black uppercase text-slate-300 leading-loose tracking-[0.2em]">Data siap diolah menjadi LKPD profesional.</p>
            </div>
          ) : (
            <div className="bg-white rounded-[3.5rem] shadow-2xl border-4 border-indigo-600 overflow-hidden flex flex-col animate-in zoom-in duration-500">
               <div className="p-6 bg-indigo-600 flex flex-wrap gap-3 justify-center no-print">
                  <button onClick={() => { navigator.clipboard.writeText(result); alert("Teks disalin!"); }} className="px-6 py-3 bg-white text-indigo-600 rounded-xl font-black uppercase text-[9px] hover:bg-indigo-50 transition-all flex items-center gap-2 shadow-sm"><i className="fas fa-copy"></i> SALIN DATA</button>
                  <button onClick={handleDownloadHtml} className="px-6 py-3 bg-white text-emerald-600 rounded-xl font-black uppercase text-[9px] hover:bg-emerald-50 transition-all flex items-center gap-2 shadow-sm"><i className="fas fa-file-code"></i> FILE CETAK (HTML)</button>
                  <button onClick={handleDownloadDoc} className="px-6 py-3 bg-white text-indigo-600 rounded-xl font-black uppercase text-[9px] hover:bg-indigo-50 transition-all flex items-center gap-2 shadow-sm"><i className="fas fa-file-word"></i> WORD</button>
               </div>
               <div className="bg-slate-50 p-8 md:p-14 overflow-auto max-h-[900px]">
                  <div ref={printAreaRef} className="bg-white shadow-lg mx-auto w-full p-10 md:p-16 text-black rounded-sm min-h-[1000px] document-body printable-area">
                    {renderCleanDocument(result)}
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default GuruToolboxPortal;

import React, { useState, useRef, useEffect } from 'react';
import { MediaToolType, VisualDesign, TeacherSettings } from '../types';
import { generateCreativeMedia } from '../services/creativeMediaService';
import { generateVisualLayout } from '../services/teacherToolsService';
import { BlockingOverlay, ProRequirementNotice } from './SharedUI';
import { validateUsageCloud, getUsageStatusCloud } from '../services/validationService';

const MediaKreatifPortal: React.FC<{ isUnlocked: boolean, gasUrl?: string, myDeviceId?: string, setGlobalBusy: (b: boolean) => void, settings: TeacherSettings }> = ({ isUnlocked, gasUrl, myDeviceId, setGlobalBusy, settings }) => {
  const [activeTool, setActiveTool] = useState<MediaToolType>('lyrics');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [visualDesign, setVisualDesign] = useState<VisualDesign | null>(null);
  const [isCloudBlocked, setIsCloudBlocked] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [dailyCount, setDailyCount] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`usage_media_v1_${today}`);
    return saved ? parseInt(saved) : 0;
  });

  const [hasBonusToday, setHasBonusToday] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`bonus_media_v1_${today}`);
    return saved === 'true';
  });

  const [proNotice, setProNotice] = useState<{show: boolean, title: string, feature: string, benefit: string, canClaimBonus?: boolean}>({
    show: false, title: '', feature: '', benefit: '', canClaimBonus: false
  });

  const [materi, setMateri] = useState('');
  const [kelas, setKelas] = useState('Kelas 4 SD');
  const [tone, setTone] = useState('Pelangi-Pelangi');
  const [sourceText, setSourceText] = useState('');

  const resultRef = useRef<HTMLDivElement>(null);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const currentLimit = hasBonusToday ? 1 : 0;

  useEffect(() => {
    const checkCloud = async () => {
      if (!isUnlocked && myDeviceId) {
        setIsValidating(true);
        const isAllowed = await getUsageStatusCloud(myDeviceId, 'Media Kreatif', currentLimit, gasUrl || "NONE");
        if (!isAllowed) setIsCloudBlocked(true);
        setIsValidating(false);
      }
    };
    checkCloud();
  }, [isUnlocked, myDeviceId, gasUrl, currentLimit]);

  const handleClaimBonus = () => {
    const today = new Date().toLocaleDateString();
    setHasBonusToday(true);
    localStorage.setItem(`bonus_media_v1_${today}`, 'true');
    setProNotice(prev => ({ ...prev, show: false }));
    setIsCloudBlocked(false); 
    alert("🌟 BONUS DIAKTIFKAN!\n\n1 Kesempatan Merakit Media telah terbuka. Silakan klik tombol Rakit Media lagi.");
  };

  const performGeneration = async () => {
    if (!materi.trim()) return alert("Mohon isi judul materi!");
    if (activeTool === 'mindmap' && !sourceText.trim()) return alert("Mohon isi detail materi!");

    setIsLoading(true);
    setGlobalBusy(true);
    setResult(null);
    setVisualDesign(null);

    try {
      if (!isUnlocked && myDeviceId) {
        const isAllowed = await validateUsageCloud(myDeviceId, 'Media Kreatif', currentLimit, gasUrl || "NONE", dailyCount);
        if (!isAllowed) {
            setIsLoading(false); setGlobalBusy(false); setIsCloudBlocked(true);
            setProNotice({ show: true, title: 'Akses Terbatas', feature: 'Media Kreatif AI', benefit: 'Upgrade ke GURU PRO untuk akses tanpa batas.', canClaimBonus: !hasBonusToday });
            return;
        }
      }

      const data = { 
        materi, 
        kelas, 
        tone, 
        text: sourceText,
        sekolah: settings.schoolName || 'Sekolah Mentari',
        guru: settings.teacherName || 'Guru Kreatif'
      };
      const res = await generateCreativeMedia(activeTool, data);
      setResult(res.text);

      if (!isUnlocked) {
        const today = new Date().toLocaleDateString();
        const newCount = dailyCount + 1;
        setDailyCount(newCount);
        localStorage.setItem(`usage_media_v1_${today}`, newCount.toString());
      }

      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
    } catch (e) {
      alert("Gagal memproses media kreatif.");
    } finally {
      setIsLoading(false);
      setGlobalBusy(false);
    }
  };

  const handleGenerate = () => {
    if (!isUnlocked) {
        if (dailyCount === 0 && !hasBonusToday) {
            setProNotice({ 
                show: true, 
                title: 'Fitur Terkunci', 
                feature: 'Media Kreatif AI', 
                benefit: 'Bapak/Ibu dapat mencoba fitur ini secara GRATIS dengan membagikan aplikasi Mentari terlebih dahulu.',
                canClaimBonus: true 
            });
            return;
        }
        if (dailyCount >= 1 || (isCloudBlocked && !hasBonusToday)) {
            setProNotice({ 
                show: true, 
                title: 'Limit Harian Tercapai', 
                feature: 'Media Kreatif Tanpa Batas', 
                benefit: 'Jatah gratis melalui share sudah digunakan. Upgrade ke GURU PRO untuk akses tanpa batas harian.', 
                canClaimBonus: false 
            });
            return;
        }
    }
    performGeneration();
  };

  const handleCanvaMagic = () => {
    if (!result) return;
    const cleanContent = result.replace(/\|/g, ' ').replace(/\n\n+/g, '\n').trim();
    const promptCanva = `
      TASK: Create a professional educational ${activeTool === 'lyrics' ? 'Song Sheet Poster' : 'Educational Mind Map'} for ${materi.toUpperCase()}.
      SCHOOL NAME: ${settings.schoolName || 'Sekolah Mentari'}
      PRIMARY TEXT CONTENT TO USE (COPY EXACTLY, NO TYPOS):
      ---
      ${cleanContent.substring(0, 1000)}
      ---
      VISUAL STYLE: High-Quality Modern Educational Graphic, Minimalist, Clean Typography, Academic Aesthetic.
      INSTRUCTION: Use ONLY the provided text. Ensure all words are spelled correctly as written in the content block above.
    `.trim();

    navigator.clipboard.writeText(promptCanva);
    alert("🚀 PROMPT MAGIC DESIGN DISALIN!\n\nLangkah:\n1. Setelah Anda klik OK maka Canva akan terbuka,\n2. CTRL+V pada kolom Magic Design,\n3. Klik Generate (tanda panah kanan).");
    window.open('https://www.canva.com/ai', '_blank');
  };

  const handleDownloadHtml = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const fullHtml = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <title>Media Kreatif - ${materi}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <style>
          @media print { .no-print { display: none; } body { padding: 0; } }
          body { background-color: #fff1f2; padding: 40px; font-family: sans-serif; }
          .container { background: white; padding: 50px; border-radius: 24px; box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1); max-width: 900px; margin: auto; border: 4px solid #f43f5e; }
        </style>
      </head>
      <body>
        <div class="no-print mb-8 text-center">
          <button onclick="window.print()" style="background:#f43f5e; color:white; padding:12px 30px; border-radius:12px; border:none; cursor:pointer; font-weight:bold; font-size:16px;">CETAK SEKARANG</button>
        </div>
        <div class="container">
          ${content}
        </div>
      </body>
      </html>
    `;
    const blob = new Blob([fullHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Media_Kreatif_${materi.replace(/\s+/g, '_')}.html`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleDownloadDoc = () => {
    if (!printAreaRef.current) return;
    const content = printAreaRef.current.innerHTML;
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><style>body { font-family: 'Arial', sans-serif; font-size: 11pt; line-height: 1.6; }</style></head><body>";
    const footer = "</body></html>";
    const blob = new Blob(['\ufeff', header + content + footer], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Media_Kreatif_${activeTool}_${materi.replace(/\s+/g, '_')}.doc`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const renderArtisticDoc = (text: string) => {
    const lines = text.split('\n');
    const elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];
    let inTable = false;

    const flushTable = (idx: number) => {
      if (currentTable.length > 0) {
        const filtered = currentTable.filter(row => !row.join('').match(/^[:\-\s|]+$/));
        if (filtered.length > 0) {
          elements.push(
            <div key={`tbl-${idx}`} className="mb-8 border-2 border-rose-100 rounded-3xl overflow-hidden bg-rose-50/30">
              <table className="w-full border-collapse text-sm text-slate-800">
                <tbody>
                  {filtered.map((r, i) => (
                    <tr key={i} className="border-b border-rose-50 last:border-0">
                      {r.map((c, j) => (
                          <td key={j} className="p-4 align-top font-bold uppercase tracking-tight">
                              {c.trim()}
                          </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        currentTable = [];
      }
      inTable = false;
    };

    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.startsWith('|')) {
        inTable = true;
        currentTable.push(trimmed.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1));
      } else {
        if (inTable) flushTable(idx);
        if (trimmed === '') return;
        const isMainHeader = trimmed.length < 40 && trimmed === trimmed.toUpperCase();
        if (isMainHeader) {
          elements.push(<div key={idx} className="bg-rose-500 text-white px-8 py-4 rounded-[2rem] mb-6 shadow-lg Museum-Text font-black uppercase text-base tracking-[0.2em] text-center">{trimmed}</div>);
        } else {
          elements.push(<p key={idx} className="mb-4 text-base text-slate-700 font-bold italic border-l-4 border-rose-200 pl-6 leading-relaxed uppercase">{trimmed}</p>);
        }
      }
    });
    if (inTable) flushTable(lines.length);
    return elements;
  };

  return (
    <div className="animate-in fade-in duration-700 space-y-8">
      <BlockingOverlay isVisible={isLoading} text="AI Studio Berkreasi..." isUnlocked={isUnlocked} />

      <ProRequirementNotice 
        isOpen={proNotice.show} 
        onClose={() => setProNotice({...proNotice, show: false})} 
        featureName={proNotice.feature} 
        benefitDesc={proNotice.benefit} 
        deviceId={myDeviceId}
        canClaimBonus={proNotice.canClaimBonus}
        onShareBonus={handleClaimBonus}
      />

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-4 space-y-6 sticky top-24 no-print">
          <div className="bg-white rounded-[3rem] p-8 shadow-xl border-4 border-rose-100 space-y-5">
             <h4 className="text-xs font-black uppercase text-rose-600 Museum-Text mb-4">Pengaturan Media</h4>
             <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Pilih Alat</label>
                  <select value={activeTool} onChange={e => setActiveTool(e.target.value as any)} className="w-full input-futuristic px-5 py-3 text-xs font-bold">
                    <option value="lyrics">Lirik Lagu Edukasi</option>
                    <option value="mindmap">Mind Map Tekstual</option>
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Materi Utama</label>
                  <input value={materi} onChange={e => setMateri(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold" placeholder="Misal: Siklus Air" />
                </div>
                {activeTool === 'lyrics' ? (
                   <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-2">Nada Lagu</label><input value={tone} onChange={e => setTone(e.target.value)} className="w-full input-futuristic px-5 py-3 text-xs font-bold" /></div>
                ) : (
                   <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-2">Detail Materi</label><textarea value={sourceText} onChange={e => setSourceText(e.target.value)} className="w-full input-futuristic px-5 py-3 h-32 resize-none text-xs" /></div>
                )}
             </div>
             <button onClick={handleGenerate} disabled={isLoading || isValidating} className="w-full py-4 bg-rose-500 text-white rounded-2xl font-black uppercase text-xs joyful-shadow">
               {isValidating ? <i className="fas fa-shield-halved fa-spin"></i> : isLoading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-icons"></i>}
               {isValidating ? 'VALIDASI...' : 'RAKIT MEDIA'}
             </button>
          </div>
        </div>
        <div className="lg:col-span-8 h-full" ref={resultRef}>
          {!result ? (
            <div className="w-full min-h-[600px] border-4 border-dashed border-rose-200 rounded-[4rem] flex flex-col items-center justify-center p-16 text-center bg-white/50">
               <div className="w-24 h-24 bg-rose-50 rounded-full flex items-center justify-center mb-8"><i className="fas fa-music text-5xl text-rose-200"></i></div>
               <h3 className="text-xl font-black uppercase text-rose-300 Museum-Text">Studio Kreatif</h3>
            </div>
          ) : (
            <div className="bg-white rounded-[3.5rem] shadow-2xl border-4 border-rose-500 overflow-hidden flex flex-col h-full animate-in zoom-in duration-500">
               <div className="p-6 bg-rose-500 flex flex-wrap gap-3 justify-center no-print">
                  <button onClick={() => { navigator.clipboard.writeText(result); alert("Disalin!"); }} className="px-5 py-2.5 bg-white text-rose-500 rounded-xl font-black uppercase text-[9px] joyful-shadow"><i className="fas fa-copy"></i> SALIN</button>
                  <button onClick={handleCanvaMagic} className="px-5 py-2.5 bg-[#00C4CC] text-white rounded-xl font-black uppercase text-[9px] joyful-shadow"><i className="fas fa-wand-magic"></i> MAGIC DESIGN CANVA</button>
                  <button onClick={handleDownloadHtml} className="px-5 py-2.5 bg-white text-emerald-600 rounded-xl font-black uppercase text-[9px] joyful-shadow"><i className="fas fa-file-code"></i> FILE CETAK</button>
                  <button onClick={handleDownloadDoc} className="px-5 py-2.5 bg-white text-rose-500 rounded-xl font-black uppercase text-[9px] joyful-shadow"><i className="fas fa-file-word"></i> WORD</button>
               </div>
               <div className="bg-slate-50 p-8 md:p-14 overflow-auto max-h-[800px]">
                  <div ref={printAreaRef} className="bg-white shadow-lg mx-auto w-full p-10 md:p-16 text-black rounded-sm min-h-[800px] document-body whitespace-pre-wrap printable-area">
                    {renderArtisticDoc(result)}
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

