                   <div className="flex justify-between items-center mb-4">
                      <div>
                        <h4 className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">Standar Ketuntasan (KKM)</h4>
                        <p className="text-[8px] font-bold text-slate-400 uppercase">Digunakan sebagai ambang batas dalam Analisis Capaian Kelas.</p>
