export const buildCanvaPrompt = (type: string, materi: string, content: string, school: string): string => {
  const cleanContent = content.replace(/\|/g, ' ').replace(/\n\n+/g, '\n').trim().substring(0, 800);
  return `CANVA MAGIC DESIGN SPECIFICATION
TYPE: Professional Educational ${type.toUpperCase()}
THEME: ${materi.toUpperCase()}
INSTITUTION: ${school}
PRIMARY CONTENT TO INCLUDE:
${cleanContent}
VISUAL STYLE: High-Quality Modern Educational Graphic, Minimalist Layout, Professional Typography, Clean Classroom Aesthetic.
INSTRUCTIONS: Organize the provided text logically. Ensure no spelling errors. Create a visually balanced design for students.`.trim();
};

