/**
 * GENERATOR PROMPT CANVA UNIVERSAL (REFINED)
 * Membersihkan seluruh simbol markdown dan menghasilkan narasi murni untuk Canva AI.
 */
export const buildCanvaPrompt = (type: string, materi: string, content: string, school: string): string => {
  // Membersihkan karakter khusus yang mengganggu input Canva AI
  const cleanContent = content
    .replace(/[#*|>\-]/g, ' ') // Hapus semua simbol Markdown
    .replace(/\n\s*\n/g, '\n') // Gabungkan baris kosong berlebih
    .replace(/\s\s+/g, ' ')     // Hapus spasi ganda
    .trim()
    .substring(0, 800);

  return `CANVA MAGIC DESIGN SPECIFICATION
  TYPE: Professional Educational ${type.toUpperCase()}
  THEME: ${materi.toUpperCase()}
  INSTITUTION: ${school}
  PRIMARY TEXT TO INCLUDE:
  ${cleanContent}
  VISUAL STYLE: Modern Educational Infographic, Premium Typography, Minimalist School Aesthetic, High-Quality Vector Illustrations.
  INSTRUCTIONS: Arrange the provided information into a logical hierarchy. Use clear subheadings and legible fonts. Ensure a professional classroom-ready presentation layout.`.replace(/\s\s+/g, ' ').trim();
};

