import { createAI, getAiModel } from "./aiConfig";
import { Type } from "@google/genai";

export interface CreativeMediaResponse {
  draft: string;
  source: string;
}

export const generateCreativeMedia = async (type: string, data: any): Promise<CreativeMediaResponse> => {
  const ai = createAI();

  const identitasStr = `INSTITUSI: ${data.sekolah} | PENYUSUN: ${data.guru} | TARGET: ${data.kelas}`;
  const materiHeader = `SUBJEK UTAMA: ${data.materi}\nDETAIL KONTEKS: ${data.text}\nLEVEL AKADEMIK: ${data.kelas}`;

  const prompt = `Anda adalah Spesialis Konten Edukasi Digital. Tugas Anda adalah merakit materi '${type}' berdasarkan input berikut:

  ${materiHeader}
  ${identitasStr}

  PERSYARATAN OUTPUT (WAJIB DIPATUHI):
  1. DILARANG KERAS menggunakan simbol Markdown seperti tanda bintang (*), pagar (#), strip (-), garis bawah (_), atau kurung siku.
  2. DILARANG menggunakan tag HTML seperti <br>.
  3. Gunakan HURUF KAPITAL untuk Judul dan Sub-Judul.
  4. Gunakan spasi baris ganda sebagai pemisah paragraf agar teks bersih.

  FORMAT JSON YANG HARUS DIHASILKAN:
  {
    "draft": "Teks terstruktur yang akan ditampilkan di aplikasi. Gunakan penomoran angka (1., 2., dst) dan judul bagian dalam ALL-CAPS. Sajikan materi dalam poin-poin deskriptif tanpa simbol.",
    "source": "Teks deskripsi naratif yang SANGAT RINCI, LENGKAP, DAN FAKTUAL untuk dijadikan sumber pengetahuan di NotebookLM. Gunakan gaya bahasa ensiklopedia. Teks ini harus mencakup seluruh aspek materi secara mendalam agar AI di NotebookLM memiliki basis data yang kuat."
  }

  PANDUAN KHUSUS TIAP ALAT:
  - INFOGRAPHIC: Fokus pada ringkasan visual, statistik, dan fakta kunci.
  - PRESENTATION: Buat outline slide per slide (SLIDE 1, SLIDE 2, dst) dengan poin konten utama.
  - MINDMAP: Gunakan hierarki konsep dari TINGKAT PUSAT ke CABANG UTAMA lalu SUB-CABANG.
  - TABLE: Sajikan data perbandingan dengan format: NAMA ITEM | KATEGORI | DESKRIPSI.
  - VIDEO_SCRIPT: Buat skenario visual dan dialog narasi.

  Hasilkan HANYA objek JSON.`;

  const response = await ai.models.generateContent({
    model: getAiModel(),
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          draft: { type: Type.STRING },
          source: { type: Type.STRING }
        },
        required: ["draft", "source"]
      },
      systemInstruction: "Anda adalah asisten cerdas yang mahir menghasilkan data JSON bersih tanpa karakter format markdown apa pun."
    }
  });

  try {
    const rawText = response.text || "{}";
    // Extra safety cleaning if AI fails to follow instructions
    const parsed = JSON.parse(rawText) as CreativeMediaResponse;
    const cleaner = (str: string) => str.replace(/[#*_\-<>]/g, '').trim();

    return {
      draft: cleaner(parsed.draft),
      source: cleaner(parsed.source)
    };
  } catch (e) {
    return { 
      draft: "Gagal memproses draft materi.", 
      source: "Gagal memproses sumber materi." 
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { MediaToolType, VisualDesign, TeacherSettings } from '../types';
import { generateCreativeMedia, CreativeMediaResponse } from '../services/creativeMediaService';
import { generateVisualLayout, buildCanvaPrompt } from '../services/teacherToolsService';
import { BlockingOverlay, ProRequirementNotice } from './SharedUI';
import { validateUsageCloud, getUsageStatusCloud } from '../services/validationService';

const MediaKreatifPortal: React.FC<{ isUnlocked: boolean, gasUrl?: string, myDeviceId?: string, setGlobalBusy: (b: boolean) => void, settings: TeacherSettings }> = ({ isUnlocked, gasUrl, myDeviceId, setGlobalBusy, settings }) => {
  const [activeTool, setActiveTool] = useState<MediaToolType>('lyrics');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<CreativeMediaResponse | null>(null);
  const [visualDesign, setVisualDesign] = useState<VisualDesign | null>(null);
  const [draftType, setDraftType] = useState<'text' | 'visual'>('text');
  const [isCloudBlocked, setIsCloudBlocked] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [dailyCount, setDailyCount] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`usage_media_v1_${today}`);
    return saved ? parseInt(saved) : 0;
  });

  const [hasBonusToday, setHasBonusToday] = useState(() => {
    const today = new Date().toLocaleDateString();
    const saved = localStorage.getItem(`bonus_media_v1_${today}`);
    return saved === 'true';
  });

  const [proNotice, setProNotice] = useState<{show: boolean, title: string, feature: string, benefit: string, canClaimBonus?: boolean}>({
    show: false, title: '', feature: '', benefit: '', canClaimBonus: false
  });

  const [materi, setMateri] = useState('');
  const [kelas, setKelas] = useState('Kelas 4 SD');
  const [tone, setTone] = useState('Pelangi-Pelangi');
  const [sourceText, setSourceText] = useState('');

  const resultRef = useRef<HTMLDivElement>(null);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const currentLimit = hasBonusToday ? 1 : 0;

  const toolInfo = {
    lyrics: { title: "Lirik Lagu Edukasi", desc: "Ubah materi hafalan menjadi lirik lagu kreatif yang mudah diingat siswa." },
    mindmap: { title: "Peta Pikiran AI", desc: "Rancang hierarki konsep yang sistematis dan mendalam dari satu topik utama." },
    infographic: { title: "Alat Info Grafis", desc: "Susun ringkasan data visual, statistik, dan fakta kunci yang siap didesain." },
    presentation: { title: "Slide Presentasi", desc: "Buat alur presentasi profesional bab demi bab untuk materi kelas Anda." },
    table: { title: "Tabel Data", desc: "Organisasikan klasifikasi atau perbandingan materi dalam format tabel yang rapi." },
    video_script: { title: "Naskah Video", desc: "Susun skenario visual dan narasi suara bergaya kreator konten edukasi." }
  };

  useEffect(() => {
    const checkCloud = async () => {
      if (!isUnlocked && myDeviceId) {
        setIsValidating(true);
        const isAllowed = await getUsageStatusCloud(myDeviceId, 'Media Kreatif', currentLimit, gasUrl || "NONE");
        if (!isAllowed) setIsCloudBlocked(true);
        setIsValidating(false);
      }
    };
    checkCloud();
  }, [isUnlocked, myDeviceId, gasUrl, currentLimit]);

  const handleClaimBonus = () => {
    const today = new Date().toLocaleDateString();
    setHasBonusToday(true);
    localStorage.setItem(`bonus_media_v1_${today}`, 'true');
    setProNotice(prev => ({ ...prev, show: false }));
    setIsCloudBlocked(false); 
    alert("🌟 BONUS DIAKTIFKAN!\n\n1 Kesempatan Merakit Media telah terbuka. Silakan klik tombol Rakit Media lagi.");
  };

  const performGeneration = async () => {
    if (!materi.trim()) return alert("Mohon isi judul materi!");
    if (activeTool !== 'lyrics' && !sourceText.trim()) return alert("Mohon isi detail materi agar AI bisa merangkum dengan lengkap!");

    setIsLoading(true);
    setGlobalBusy(true);
    setResult(null);
    setVisualDesign(null);

    try {
      if (!isUnlocked && myDeviceId) {
        const isAllowed = await validateUsageCloud(myDeviceId, 'Media Kreatif', currentLimit, gasUrl || "NONE", dailyCount);
        if (!isAllowed) {
            setIsLoading(false); setGlobalBusy(false); setIsCloudBlocked(true);
            setProNotice({ show: true, title: 'Akses Terbatas', feature: 'Media Kreatif AI', benefit: 'Upgrade ke GURU PRO untuk akses tanpa batas.', canClaimBonus: !hasBonusToday });
            return;
        }
      }

      const data = { 
        materi, 
        kelas, 
        tone, 
        text: sourceText,
        sekolah: settings.schoolName || 'Sekolah Mentari',
        guru: settings.teacherName || 'Guru Kreatif'
      };

      const res = await generateCreativeMedia(activeTool, data);

      if (draftType === 'visual') {
        const visual = await generateVisualLayout(materi, res.draft, activeTool);
        setVisualDesign(visual);
      }

      setResult(res);

      if (!isUnlocked) {
        const today = new Date().toLocaleDateString();
        const newCount = dailyCount + 1;
        setDailyCount(newCount);
        localStorage.setItem(`usage_media_v1_${today}`, newCount.toString());
      }

      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
