        alert("⚠️ AKSES AI TERBATAS (LIMIT)!\n\nProses merakit simulasi lab maya membutuhkan daya komputasi tinggi yang saat ini sedang penuh. \n\nSilakan tunggu 1 menit atau gunakan engine 'Flash' untuk akses lebih lancar.");
      } else {
        alert("Gagal merakit karya. Silakan coba lagi.");
