            <input value={materi} onChange={e => setMateri(e.target.value)} className="w-full input-futuristic px-5 py-3.5" placeholder="Contoh: Peredaran Darah Manusia" />
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Tingkat Kelas</label>
