          <i className="fas fa-award text-amber-500"></i> Gamifikasi & Apresiasi
        </h2>
        <div className="flex gap-2 mb-6 overflow-x-auto no-scrollbar py-2">
          {['certificate', 'homeproject', 'mystery'].map(t => (
            <button key={t} onClick={() => setActiveTool(t as any)} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap ${activeTool === t ? 'bg-amber-500 text-white shadow-lg' : 'bg-slate-50 text-slate-400'}`}>
              {t.toUpperCase()}
            </button>
          ))}
        </div>
        {activeTool === 'certificate' && (
          <select value={targetSiswa} onChange={e => setTargetSiswa(e.target.value)} className="w-full input-futuristic px-5 py-3 mb-4">
            <option value="">Pilih Siswa...</option>
            {students.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
          </select>
        )}
        <button onClick={handleGenerate} disabled={isLoading} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-black uppercase">
          {isLoading ? 'MERANCANG APRESIASI...' : 'RAKIT KONTEN GAMIFIKASI'}
        </button>
      </div>

      <div ref={resultRef} className="animate-in fade-in duration-700">
        {result && (
          <div className="bg-white p-10 rounded-[3rem] border-4 border-amber-100 shadow-2xl markdown-container">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{result}</ReactMarkdown>
          </div>
        )}
      </div>
    </div>
  );
};

export default EngagementPortal;

import React, { useState, useRef } from 'react';
import { generateCommunicationContent } from '../services/communicationService';
import { TeacherSettings, Student } from '../types';

interface CommunicationPortalProps {
  isUnlocked: boolean;
  gasUrl: string;
  students: Student[];
  settings: TeacherSettings;
  setGlobalBusy: (b: boolean) => void;
}

const CommunicationPortal: React.FC<CommunicationPortalProps> = ({
  setGlobalBusy, isUnlocked, settings, students
}) => {
  // Fix: Defined isLoading, result, and resultRef
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState('');
  const resultRef = useRef<HTMLDivElement>(null);

  const [activeTool, setActiveTool] = useState<'bulletin' | 'parent_msg'>('bulletin');
  const [targetSiswa, setTargetSiswa] = useState('');

  const handleGenerate = async () => {
    setIsLoading(true);
    setGlobalBusy(true);
    try {
      const data = { 
        sekolah: settings.schoolName, 
        kelas: settings.className, 
        aktivitas: 'Belajar tentang tata surya dan membuat poster digital.',
        champions: 'Budi, Susi, dan Andi.',
        namaSiswa: targetSiswa,
        pencapaian: 'Mendapat nilai sempurna di kuis matematika.',
        namaGuru: settings.teacherName
      };
      const response = await generateCommunicationContent(activeTool, data);
      setResult(response.text);
      // Fix: Used resultRef correctly
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
    } catch (e: any) {
      // Fix: Re-implemented catch block with rate limit handling from original snippet
      if (e.message?.includes('429') || e.message?.includes('Quota') || e.message?.includes('limit')) {
        alert("⚠️ KOMUNIKASI AI LIMIT!\n\nSistem AI sedang beristirahat sejenak karena kuota permintaan per menit tercapai. \n\nSilakan coba lagi dalam 1 menit atau pilih engine 'Flash' di tab Konfigurasi.");
      } else {
        alert("Gagal merancang pesan komunikasi.");
      }
    } finally {
      // Fix: Used setIsLoading and setGlobalBusy
      setIsLoading(false);
      setGlobalBusy(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[3rem] border-4 border-slate-100 shadow-sm">
        <h2 className="text-2xl font-black text-slate-800 Museum-Text uppercase mb-6 flex items-center gap-3">
          <i className="fas fa-bullhorn text-emerald-600"></i> Komunikasi Sekolah
        </h2>
        <div className="flex gap-2 mb-6">
          <button onClick={() => setActiveTool('bulletin')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase ${activeTool === 'bulletin' ? 'bg-emerald-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400'}`}>Buletin Kelas</button>
          <button onClick={() => setActiveTool('parent_msg')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase ${activeTool === 'parent_msg' ? 'bg-emerald-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400'}`}>Pesan Orang Tua</button>
        </div>
        {activeTool === 'parent_msg' && (
          <select value={targetSiswa} onChange={e => setTargetSiswa(e.target.value)} className="w-full input-futuristic px-5 py-3 mb-4">
            <option value="">Pilih Siswa...</option>
            {students.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
          </select>
        )}
        <button onClick={handleGenerate} disabled={isLoading} className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-black uppercase">
          {isLoading ? 'MENYUSUN PESAN...' : 'GENERATE PESAN WHATSAPP'}
        </button>
      </div>

      <div ref={resultRef} className="animate-in fade-in duration-700">
        {result && (
          <div className="bg-white p-10 rounded-[3rem] border-4 border-emerald-100 shadow-2xl relative">
            <div className="flex justify-between items-center mb-6">
               <h4 className="text-sm font-black uppercase text-emerald-700 tracking-widest">Draft Pesan Siap Kirim</h4>
               <button onClick={() => { navigator.clipboard.writeText(result); alert("Pesan disalin!"); }} className="text-blue-600 font-black uppercase text-[10px] hover:underline">Salin Teks</button>
            </div>
            <div className="bg-slate-50 p-8 rounded-2xl font-medium leading-relaxed whitespace-pre-wrap text-slate-700 border-2 border-white shadow-inner">{result}</div>
          </div>
        )}
      </div>
    </div>
  );
};

export default CommunicationPortal;
